// Interop test: TypeScript SDK <-> Rust krymux-tunnel binary
// (../../target/release/krymux-tunnel.exe, override with ECTUN_BIN).
//
// Phase A: Rust server + TS client (identities generated by the TS SDK, so the
//          Rust side must accept our Ed25519 certs/fingerprints) — echo 1 MiB
//          byte-exact for each compression mode, deny unrouted targets, reject
//          a non-whitelisted Rust-generated key.
// Phase B: TS server + Rust client driven through a SOCKS5 frontend — echo
//          1 MiB byte-exact for each compression mode.
//
// Patterns follow ../../interop/test-interop.mjs; waits are readiness polls,
// not fixed sleeps.
//
//   npx tsx scripts/interop-with-rust.ts

import { spawn, type ChildProcess } from 'node:child_process';
import * as net from 'node:net';
import * as crypto from 'node:crypto';
import { Buffer } from 'node:buffer';
import { mkdtempSync, mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import * as assert from 'node:assert/strict';
import {
  EctunClient, createProxyServer, generateIdentity, loadIdentity, saveIdentity, noopLogger,
} from '../src/index.js';
import type { TunnelStream } from '../src/index.js';

// Rust binary: ECTUN_BIN env var, or the release build at the repo root
// (ectun-rs/target/release/krymux-tunnel.exe — three levels up from scripts/).
const RS = process.env.ECTUN_BIN
  ?? fileURLToPath(new URL('../../../target/release/krymux-tunnel.exe', import.meta.url));
const KEYDIR = mkdtempSync(join(tmpdir(), 'krymux-ts-interop-'));
mkdirSync(KEYDIR, { recursive: true });

const PASS: string[] = [];
const FAIL: string[] = [];
function report(name: string, err?: unknown): void {
  if (err) {
    FAIL.push(name);
    console.error(`FAIL ${name}: ${err instanceof Error ? err.message : String(err)}`);
  } else {
    PASS.push(name);
    console.log(`ok   ${name}`);
  }
}

const tmpJson = (p: string, o: unknown) => writeFileSync(p, JSON.stringify(o, null, 2));

// ---------- process / network helpers (event-driven, no fixed sleeps) ----------

type Spawned = { proc: ChildProcess; stderr: string };

function start(cmd: string, args: string[]): Promise<Spawned> {
  return new Promise((resolve, reject) => {
    const proc = spawn(cmd, args, { stdio: ['ignore', 'pipe', 'pipe'] });
    let stderr = '';
    proc.stderr?.on('data', (c: Buffer) => {
      stderr += c.toString();
    });
    proc.stdout?.on('data', () => {});
    proc.once('error', reject);
    proc.once('spawn', () => resolve({ proc, stderr }));
  });
}

function runToExit(cmd: string, args: string[], timeoutMs = 15000): Promise<string> {
  return new Promise((resolve, reject) => {
    const p = spawn(cmd, args, { stdio: ['ignore', 'pipe', 'pipe'] });
    let out = '';
    const t = setTimeout(() => {
      p.kill();
      reject(new Error(`timeout: ${cmd} ${args.join(' ')}`));
    }, timeoutMs);
    p.stdout?.on('data', (c: Buffer) => {
      out += c.toString();
    });
    p.stderr?.on('data', (c: Buffer) => {
      out += c.toString();
    });
    p.once('error', (e) => {
      clearTimeout(t);
      reject(e);
    });
    p.once('exit', () => {
      clearTimeout(t);
      resolve(out);
    });
  });
}

/** Rust `keygen`: writes <name>.key.pem/<name>.crt.pem, prints the fingerprint. */
async function keygen(args: string[]): Promise<string> {
  const out = await runToExit(RS, ['keygen', ...args]);
  const m = out.match(/fingerprint: (sha256:[0-9a-f]{64})/);
  if (!m) throw new Error('keygen failed: ' + out);
  return m[1]!;
}

function waitExit(proc: ChildProcess, timeoutMs = 8000): Promise<void> {
  return new Promise((resolve, reject) => {
    if (proc.exitCode !== null) return resolve();
    const t = setTimeout(() => reject(new Error('process did not exit')), timeoutMs);
    proc.once('exit', () => {
      clearTimeout(t);
      resolve();
    });
  });
}

/** Poll until a TCP port accepts connections (readiness probe). */
function waitTcp(host: string, port: number, timeoutMs = 10000): Promise<void> {
  const deadline = Date.now() + timeoutMs;
  return new Promise((resolve, reject) => {
    const attempt = () => {
      const sock = net.connect({ host, port });
      sock.once('connect', () => {
        sock.destroy();
        resolve();
      });
      sock.once('error', () => {
        sock.destroy();
        if (Date.now() > deadline) reject(new Error(`port never opened: ${host}:${port}`));
        else setTimeout(attempt, 60);
      });
    };
    attempt();
  });
}

function freePort(): Promise<number> {
  return new Promise((resolve, reject) => {
    const srv = net.createServer();
    srv.listen(0, '127.0.0.1', () => {
      const port = (srv.address() as net.AddressInfo).port;
      srv.close(() => resolve(port));
    });
    srv.once('error', reject);
  });
}

function startEcho(): Promise<{ srv: net.Server; port: number }> {
  const srv = net.createServer((s) => s.pipe(s));
  return new Promise((r) => srv.listen(0, '127.0.0.1', () => r({ srv, port: (srv.address() as net.AddressInfo).port })));
}

async function readAll(stream: TunnelStream): Promise<Buffer> {
  const parts: Buffer[] = [];
  for await (const c of stream) parts.push(c as Buffer);
  return Buffer.concat(parts);
}

/** Exactly 1 MiB: half random (incompressible), half repeating (compressible). */
function payload1MiB(): Buffer {
  const half = 512 * 1024;
  const pattern = Buffer.from('krymux-ts-interop-payload ');
  const reps = Math.ceil(half / pattern.length);
  const compressible = Buffer.concat(Array(reps).fill(pattern)).subarray(0, half);
  return Buffer.concat([crypto.randomBytes(half), compressible]);
}

// ---------- SOCKS5 client (drives the Rust client's frontend) ----------

function once(ev: net.Socket, name: string): Promise<void> {
  return new Promise((r) => ev.once(name, r));
}

async function readN(sock: net.Socket, n: number): Promise<Buffer> {
  return new Promise((resolve) => {
    const chunks: Buffer[] = [];
    const onData = (c: Buffer) => {
      chunks.push(c);
      if (Buffer.concat(chunks).length >= n) {
        sock.off('data', onData);
        resolve(Buffer.concat(chunks).subarray(0, n));
      }
    };
    sock.on('data', onData);
  });
}

async function socks5Echo(proxyHost: string, proxyPort: number, host: string, port: number, payload: Buffer): Promise<Buffer> {
  const sock = net.connect({ host: proxyHost, port: proxyPort });
  await once(sock, 'connect');
  sock.write(Buffer.from([5, 1, 0]));
  await readN(sock, 2);
  const h = Buffer.from(host);
  sock.write(Buffer.from([5, 1, 0, 3, h.length, ...h, port >> 8, port & 0xff]));
  const rep = await readN(sock, 10);
  if (rep[1] !== 0) throw new Error('socks5 reply ' + rep[1]);
  sock.write(payload);
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let got = 0;
    sock.on('data', (c: Buffer) => {
      chunks.push(c);
      got += c.length;
      if (got >= payload.length) {
        sock.destroy();
        resolve(Buffer.concat(chunks));
      }
    });
    sock.once('error', reject);
    sock.once('close', () => resolve(Buffer.concat(chunks)));
  });
}

// global watchdog: never hang the CI
setTimeout(() => {
  console.error('interop: GLOBAL TIMEOUT');
  process.exit(2);
}, 180_000);

// ================= Phase A: Rust server + TS client =================
{
  const procs: ChildProcess[] = [];
  const echo = await startEcho();
  const tunnelPort = await freePort();
  let client: EctunClient | null = null;

  try {
    // identities generated by the TS SDK; the Rust side must load our PEMs
    // and accept our fingerprints byte-for-byte
    const serverId = generateIdentity({ cn: 'interop-ts-server' });
    saveIdentity(KEYDIR, serverId, { name: 'server' });
    const aliceId = generateIdentity({ cn: 'interop-ts-alice' });
    saveIdentity(KEYDIR, aliceId, { name: 'alice' });
    // rust-generated identity, NOT in the whitelist
    await keygen(['--out', KEYDIR, '--role', 'client', '--name', 'mallory']);

    tmpJson(join(KEYDIR, 'server.json'), {
      listen: `127.0.0.1:${tunnelPort}`,
      identity: { key: join(KEYDIR, 'server.key.pem'), cert: join(KEYDIR, 'server.crt.pem') },
      auth: { mode: 'whitelist', fingerprints: [aliceId.fingerprint] },
      routes: [
        { host: ['echo'], upstream: ['127.0.0.1', echo.port] },
      ],
      clientTargets: { enabled: false },
    });
    const rsServer = (await start(RS, ['server', '--config', join(KEYDIR, 'server.json')])).proc;
    procs.push(rsServer);
    await waitTcp('127.0.0.1', tunnelPort);

    // TS client with TS-generated identity, loaded back from disk
    const alice = loadIdentity({ key: join(KEYDIR, 'alice.key.pem'), cert: join(KEYDIR, 'alice.crt.pem') });
    assert.equal(alice.fingerprint, aliceId.fingerprint, 'loadIdentity fingerprint round-trip');
    client = await EctunClient.connect({
      endpoint: `127.0.0.1:${tunnelPort}`,
      identity: alice,
      serverFingerprint: serverId.fingerprint,
    });

    // 1 MiB echo per compression mode, byte-exact
    for (const algo of ['none', 'deflate', 'auto']) {
      try {
        const payload = payload1MiB();
        const s = await client.openStream({ host: 'echo', port: 9, compression: algo });
        s.write(payload);
        s.end();
        const out = await readAll(s);
        assert.equal(out.length, payload.length, 'length');
        assert.ok(out.equals(payload), 'bytes');
        report(`A: echo ${algo} 1MiB byte-exact (ts client -> rust server)`);
      } catch (e) {
        report(`A: echo ${algo}`, e);
      }
    }

    // unrouted target denied
    try {
      await assert.rejects(
        () => client!.openStream({ host: 'nope.example', port: 80 }),
        (e: Error) => /no route|denied/i.test(e.message),
      );
      report('A: unrouted target denied');
    } catch (e) {
      report('A: deny', e);
    }

    // non-whitelisted key rejected (rust-generated mallory, fail-closed)
    try {
      const mallory = loadIdentity({ key: join(KEYDIR, 'mallory.key.pem'), cert: join(KEYDIR, 'mallory.crt.pem') });
      await assert.rejects(
        () => EctunClient.connect({
          endpoint: `127.0.0.1:${tunnelPort}`,
          identity: mallory,
          serverFingerprint: serverId.fingerprint,
        }),
        (e: Error) => /handshake|certificate|socket|ECONNRESET|closed|verification/i.test(e.message),
      );
      report('A: non-whitelisted key rejected');
    } catch (e) {
      report('A: whitelist reject', e);
    }
  } catch (e) {
    report('A: setup', e);
  } finally {
    client?.close('phase-a done');
    for (const p of procs) p.kill();
    await Promise.allSettled(procs.map((p) => waitExit(p)));
    echo.srv.close();
  }
}

// ================= Phase B: TS server + Rust client (socks5) =================
{
  const echo = await startEcho();
  let tsServer: ReturnType<typeof createProxyServer> | null = null;
  const procs: ChildProcess[] = [];
  try {
    const serverId = generateIdentity({ cn: 'interop-ts-server-b' });
    const bobFp = await keygen(['--out', KEYDIR, '--role', 'client', '--name', 'bob']);

    tsServer = createProxyServer({
      listen: '127.0.0.1:0',
      identity: serverId,
      auth: { mode: 'whitelist', fingerprints: [bobFp] },
      routes: [{ host: '*', upstream: { host: '127.0.0.1', port: echo.port } }],
      log: noopLogger(),
    });
    await tsServer.start();
    const tunnelPort = (tsServer.address() as net.AddressInfo).port;

    for (const comp of ['none', 'deflate', 'auto']) {
      const socksPort = await freePort();
      tmpJson(join(KEYDIR, 'rs-client.json'), {
        endpoint: `127.0.0.1:${tunnelPort}`,
        identity: { key: join(KEYDIR, 'bob.key.pem'), cert: join(KEYDIR, 'bob.crt.pem') },
        serverFingerprint: serverId.fingerprint,
        socks5: `127.0.0.1:${socksPort}`,
        compression: comp,
      });
      const rsClient = (await start(RS, ['client', '--config', join(KEYDIR, 'rs-client.json')])).proc;
      procs.push(rsClient);
      await waitTcp('127.0.0.1', socksPort, 10000);
      try {
        const payload = payload1MiB();
        const out = await socks5Echo('127.0.0.1', socksPort, 'echo.x', 9, payload);
        assert.equal(out.length, payload.length, 'length');
        assert.ok(out.equals(payload), 'bytes');
        report(`B: rust client (${comp}) -> ts server, 1MiB echo via socks5`);
      } catch (e) {
        report(`B: ${comp}`, e);
      }
      rsClient.kill();
      await waitExit(rsClient);
    }
  } catch (e) {
    report('B: setup', e);
  } finally {
    for (const p of procs) p.kill();
    await Promise.allSettled(procs.map((p) => waitExit(p)));
    await tsServer?.stop();
    echo.srv.close();
  }
}

console.log(`\ninterop: ${PASS.length} passed, ${FAIL.length} failed`);
try {
  rmSync(KEYDIR, { recursive: true, force: true });
} catch {
  /* best effort on Windows */
}
process.exit(FAIL.length ? 1 : 0);

/**
 * @krymux/sdk public surface — the package entry point.
 * Re-exports the full protocol stack so applications can import everything
 * from '@krymux/sdk': identity/keys, TLS contexts, server, client,
 * multiplexing, framing, compression, routing, and helpers.
 */

export {
  generateIdentity, loadIdentity, saveIdentity, buildSelfSignedCert,
  fingerprintOf, normalizeFingerprint, peerFingerprint, X509Certificate,
} from './keys.js';
export type { Identity } from './keys.js';
export { createProxyServer, createServer } from './server.js';
export type { ProxyServer, ProxyServerOptions, ServerStats } from './server.js';
export { EctunClient } from './client.js';
export type { ConnectOptions } from './client.js';
export { MuxSession } from './mux.js';
export type { MuxOptions, MuxStats, OpenStreamOptions } from './mux.js';
export { TunnelStream } from './stream.js';
export type { StreamTarget, StreamStats } from './stream.js';
export { compileRoutes } from './router.js';
export type { RouteConfig, RouteDecision, UpstreamAddr, UpstreamInput, ClientTargetsConfig } from './router.js';
export {
  serverTlsOptions, clientTlsOptions, authorizePeer, verifyServerPin, compileAuth, ALPN,
} from './tlsctx.js';
export type { AuthConfig, CompiledAuth, AuthVerdict } from './tlsctx.js';
export {
  FT, FLAG, CLOSE_CODES, ProtocolError, encodeFrame, FrameParser,
} from './frame.js';
export type { ParsedFrame } from './frame.js';
export {
  supportedAlgorithms, negotiate, baseAlgo, parseLevel, looksPrecompressed,
  createCompressContext, createDecompressContext,
  ALGO_NONE, ALGO_DEFLATE,
} from './compress.js';
export type { CompCtx } from './compress.js';
export {
  createLog, noopLogger, parseTarget, normalizeHost, hostMatches,
} from './util.js';
export type { Logger, ParsedTarget, TargetInput } from './util.js';

/** Semantic version of this package. */
export const VERSION = '0.1.0';

/** Wire protocol version (Krymux CMPX); must match across implementations. */
export const PROTOCOL_VERSION = 1;

// Identity layer: Ed25519 keypairs, self-signed X.509 certificates (built with src/der.ts),
// and SPKI fingerprints used as the canonical wire identity (like SSH/WireGuard key IDs).
//
// The fingerprint is "sha256:" + hex(sha256(SPKI DER)) — byte-identical to the Rust
// implementation (crates/krymux/src/keys.rs), so whitelists and pins transfer 1:1.

import { Buffer } from 'node:buffer';
import {
  generateKeyPairSync, createHash, createPublicKey, sign as cryptoSign,
  randomBytes, X509Certificate, createPrivateKey,
} from 'node:crypto';
import type { KeyObject, JsonWebKey } from 'node:crypto';
import type { TLSSocket } from 'node:tls';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import * as der from './der.js';

export { X509Certificate };

export const OID_ED25519 = '1.3.101.112';

/** A generated or loaded identity. */
export interface Identity {
  privateKey: KeyObject;
  publicKey: KeyObject;
  keyPem: string;
  certPem: string;
  fingerprint: string;
  /** Only set by loadIdentity(). */
  x509?: X509Certificate;
  /** Only set by loadIdentity(). */
  peerName?: string;
}

/** sha256(SPKI DER), formatted "sha256:<64 lowercase hex>". Stable across cert regeneration. */
export function fingerprintOf(publicKey: KeyObject): string {
  const spki = publicKey.export({ type: 'spki', format: 'der' });
  return 'sha256:' + createHash('sha256').update(spki).digest('hex');
}

function wrap64(derBuf: Buffer): string {
  const b64 = derBuf.toString('base64');
  const lines = b64.match(/.{1,64}/g) ?? [];
  return `-----BEGIN CERTIFICATE-----\n${lines.join('\n')}\n-----END CERTIFICATE-----\n`;
}

/**
 * Build a minimal self-signed Ed25519 certificate.
 * - CN = "<cn> <fingerprint prefix>"; SAN DNS:krymux (name checks are bypassed by our
 *   pinning, SAN kept for interop)
 * - validity: 20 years (UTCTime, capped by the year 2049 per DER)
 */
export function buildSelfSignedCert(
  keyPair: { publicKey: KeyObject; privateKey: KeyObject },
  { cn = 'krymux', days = 7300 }: { cn?: string; days?: number } = {},
): { pem: string; x509: X509Certificate; fingerprint: string } {
  const rawPub = keyPair.publicKey.export({ format: 'jwk' }) as JsonWebKey;
  // For ed25519, raw public key = base64url "x" of the JWK
  if (!rawPub.x) throw new Error('ed25519 public key JWK has no "x"');
  const raw = Buffer.from(rawPub.x, 'base64url');
  const fp = fingerprintOf(keyPair.publicKey).slice('sha256:'.length);
  const commonName = `${cn} ${fp.slice(0, 16)}`;

  const algId = der.ed25519AlgId();
  const name = der.seq(der.rdnSet(der.seq(der.oid('2.5.4.3'), der.utf8Str(commonName))));

  const notBefore = new Date(Date.now() - 24 * 3600 * 1000);
  const notAfter = new Date(Date.now() + days * 24 * 3600 * 1000);
  // UTCTime is only defined up to 2049; clamp.
  if (notAfter.getUTCFullYear() > 2049) notAfter.setUTCFullYear(2049, 11, 31);
  const validity = der.seq(der.utcTime(notBefore), der.utcTime(notAfter));

  let serial = randomBytes(16);
  if (serial[0] === 0) serial[0] = 1; // keep positive
  if (serial[0]! & 0x80) serial = Buffer.concat([Buffer.from([0]), serial]);

  const spki = der.ed25519Spki(raw);

  const extBasicConstraints = der.seq(
    der.oid('2.5.29.19'), der.bool(true), der.octetString(der.seq()),
  );
  const extSan = der.seq(
    der.oid('2.5.29.17'), der.octetString(der.seq(der.ctxPrimitive(2, Buffer.from('krymux', 'ascii')))),
  );
  const extensions = der.ctxExplicit(3, der.seq(extBasicConstraints, extSan));

  const tbs = der.seq(
    der.ctxExplicit(0, der.int(2)), // version v3
    der.int(serial),
    algId,
    name, // issuer (self-signed)
    validity,
    name, // subject
    spki,
    extensions,
  );

  const sig = cryptoSign(null, tbs, keyPair.privateKey);
  const cert = der.seq(tbs, algId, der.bitString(sig));
  const pem = wrap64(cert);

  // Fail fast if we produced anything Node/OpenSSL refuses to parse or verify.
  const x509 = new X509Certificate(pem);
  if (!x509.verify(keyPair.publicKey)) {
    throw new Error('self-signed certificate failed self-verification');
  }
  return { pem, x509, fingerprint: 'sha256:' + fp };
}

/** Generate an identity: Ed25519 keypair + self-signed cert + fingerprint. */
export function generateIdentity({ cn = 'krymux', days = 7300 }: { cn?: string; days?: number } = {}): Identity {
  const keyPair = generateKeyPairSync('ed25519');
  const { pem, fingerprint } = buildSelfSignedCert(keyPair, { cn, days });
  return {
    privateKey: keyPair.privateKey,
    publicKey: keyPair.publicKey,
    keyPem: keyPair.privateKey.export({ type: 'pkcs8', format: 'pem' }).toString(),
    certPem: pem,
    fingerprint,
  };
}

/**
 * Accept flexible fingerprint inputs:
 *  - "sha256:<hex>" / bare 64-char hex
 *  - base64 SPKI DER (44 chars, as exported by publicKey.export({type:'spki',format:'der'}))
 *  - a PEM public key / certificate
 */
export function normalizeFingerprint(input: string): string {
  if (!input) throw new Error('empty fingerprint input');
  const s = String(input).trim();
  if (s.startsWith('sha256:')) {
    const hex = s.slice(7).replace(/[:\s]/g, '').toLowerCase();
    if (!/^[0-9a-f]{64}$/.test(hex)) throw new Error(`bad sha256 fingerprint: ${s}`);
    return 'sha256:' + hex;
  }
  if (/^[0-9a-f:]{64,79}$/i.test(s) && s.replace(/:/g, '').length === 64) {
    return 'sha256:' + s.replace(/:/g, '').toLowerCase();
  }
  if (/^sha256-/.test(s)) { // JWKS-style
    return 'sha256:' + Buffer.from(s.slice(7), 'base64url').toString('hex');
  }
  if (s.startsWith('-----')) { // PEM: public key or certificate
    const asKey = createPublicKey(s);
    return fingerprintOf(asKey);
  }
  if (/^[A-Za-z0-9+/=]+$/.test(s) && s.length >= 40) { // base64 SPKI DER
    const derBuf = Buffer.from(s, 'base64');
    if (derBuf.length >= 40 && derBuf.length <= 120 && derBuf[0] === 0x30) {
      return 'sha256:' + createHash('sha256').update(derBuf).digest('hex');
    }
  }
  throw new Error(`unrecognized fingerprint format: ${String(input).slice(0, 40)}...`);
}

/** Extract the SPKI fingerprint of the peer certificate of a live TLS socket. */
export function peerFingerprint(tlsSocket: TLSSocket): string | null {
  const cert = tlsSocket.getPeerCertificate() as ReturnType<TLSSocket['getPeerCertificate']> & { empty?: boolean };
  if (!cert || cert.empty) return null;
  try {
    const rawDer = Buffer.isBuffer(cert.raw) ? cert.raw : null;
    if (!rawDer) return null;
    const x509 = new X509Certificate(rawDer);
    return fingerprintOf(x509.publicKey);
  } catch {
    return null;
  }
}

function readMaybe(pathOrPem: string): string | null {
  if (typeof pathOrPem !== 'string') return null;
  if (pathOrPem.includes('-----BEGIN')) return pathOrPem;
  const p = resolve(pathOrPem);
  if (!existsSync(p)) throw new Error(`file not found: ${p}`);
  return readFileSync(p, 'utf8');
}

/** Load an identity from PEM strings or file paths. */
export function loadIdentity(
  { key: keyIn, cert: certIn, passphrase }: { key?: string; cert?: string; passphrase?: string } = {},
): Identity {
  const keyPem = readMaybe(keyIn ?? '');
  const certPem = readMaybe(certIn ?? '');
  if (!keyPem || !certPem) throw new Error('identity requires key and cert (PEM or path)');
  const privateKey = passphrase
    ? createPrivateKey({ key: keyPem, passphrase })
    : createPrivateKey(keyPem);
  const x509 = new X509Certificate(certPem);
  const publicKey = x509.publicKey;
  if (fingerprintOf(publicKey) !== fingerprintOf(createPublicKey(privateKey))) {
    throw new Error('identity key does not match certificate');
  }
  return {
    privateKey,
    publicKey,
    x509,
    keyPem,
    certPem,
    fingerprint: fingerprintOf(publicKey),
    peerName: (x509.subject ?? '').toString(),
  };
}

/** Persist an identity to <dir>/<name>.key.pem + <name>.crt.pem + identity.json. */
export function saveIdentity(
  dir: string,
  identity: Identity,
  { name = 'server' }: { name?: string } = {},
): { keyPath: string; certPath: string; fingerprint: string } {
  mkdirSync(dir, { recursive: true });
  const keyPath = join(dir, `${name}.key.pem`);
  const certPath = join(dir, `${name}.crt.pem`);
  writeFileSync(keyPath, identity.keyPem, { mode: 0o600 });
  writeFileSync(certPath, identity.certPem);
  writeFileSync(join(dir, `${name}.identity.json`), JSON.stringify({
    name,
    fingerprint: identity.fingerprint,
    key: keyPath,
    cert: certPath,
    createdAt: new Date().toISOString(),
  }, null, 2));
  return { keyPath, certPath, fingerprint: identity.fingerprint };
}

// Minimal DER encoder — just enough for a self-signed Ed25519 X.509 certificate.
// Pure functions returning Buffers, composed bottom-up.

import { Buffer } from 'node:buffer';

function concat(parts: Array<Buffer | null | undefined>): Buffer {
  return Buffer.concat(parts.filter((p): p is Buffer => !!p && p.length > 0));
}

function derLen(n: number): Buffer {
  if (n < 0x80) return Buffer.from([n]);
  const bytes: number[] = [];
  let v = n;
  while (v > 0) {
    bytes.unshift(v & 0xff);
    v = Math.floor(v / 0x100);
  }
  return Buffer.from([0x80 | bytes.length, ...bytes]);
}

function tlv(tag: number, content: Buffer): Buffer {
  return concat([Buffer.from([tag]), derLen(content.length), content]);
}

/** SEQUENCE */
export function seq(...contents: Array<Buffer | null | undefined>): Buffer {
  return tlv(0x30, concat(contents));
}

/** SET */
export function setOf(...contents: Array<Buffer | null | undefined>): Buffer {
  return tlv(0x31, concat(contents));
}

/** SET OF (same wire form; used for RDN sets) */
export const rdnSet = setOf;

/** INTEGER from a Buffer (already unsigned, we fix sign) or a small number. */
export function int(value: number | Buffer): Buffer {
  let bytes: Buffer;
  if (Buffer.isBuffer(value)) {
    bytes = value;
    while (bytes.length > 1 && bytes[0] === 0) bytes = bytes.subarray(1);
    if (bytes.length === 0) bytes = Buffer.from([0]);
    if (bytes[0]! & 0x80) bytes = concat([Buffer.from([0]), bytes]);
  } else {
    bytes = Buffer.alloc(4);
    bytes.writeUInt32BE(value >>> 0, 0);
    let i = 0;
    while (i < 3 && bytes[i] === 0) i++;
    bytes = bytes.subarray(i);
    if (bytes[0]! & 0x80) bytes = concat([Buffer.from([0]), bytes]);
  }
  return tlv(0x02, bytes);
}

/** OBJECT IDENTIFIER from a dotted string, e.g. "1.3.101.112". */
export function oid(dotted: string): Buffer {
  const parts = dotted.split('.').map((s) => Number(s));
  const body: number[] = [];
  body.push(parts[0]! * 40 + parts[1]!);
  for (let i = 2; i < parts.length; i++) {
    let v = parts[i]!;
    const stack = [v & 0x7f];
    v = Math.floor(v / 128);
    while (v > 0) {
      stack.unshift((v & 0x7f) | 0x80);
      v = Math.floor(v / 128);
    }
    body.push(...stack);
  }
  return tlv(0x06, Buffer.from(body));
}

/** BIT STRING (unused-bits = 0). */
export function bitString(buf: Buffer): Buffer {
  return tlv(0x03, concat([Buffer.from([0x00]), buf]));
}

/** OCTET STRING */
export function octetString(buf: Buffer | number[]): Buffer {
  return tlv(0x04, Buffer.isBuffer(buf) ? buf : Buffer.from(buf));
}

/** UTF8String */
export function utf8Str(s: string): Buffer {
  return tlv(0x0c, Buffer.from(s, 'utf8'));
}

/** UTCTime (dates 1950..2049): YYMMDDHHMMSSZ */
export function utcTime(date: Date): Buffer {
  const p = (n: number) => String(n).padStart(2, '0');
  const d = date;
  const s =
    `${p(d.getUTCFullYear() % 100)}${p(d.getUTCMonth() + 1)}${p(d.getUTCDate())}` +
    `${p(d.getUTCHours())}${p(d.getUTCMinutes())}${p(d.getUTCSeconds())}Z`;
  return tlv(0x17, Buffer.from(s, 'ascii'));
}

/** BOOLEAN */
export function bool(b: boolean): Buffer {
  return tlv(0x01, Buffer.from([b ? 0xff : 0x00]));
}

/** context-specific constructed [n] EXPLICIT wrapper */
export function ctxExplicit(n: number, content: Buffer): Buffer {
  return tlv(0xa0 | n, content);
}

/** context-specific primitive [n] (e.g. [2] dNSName in SAN) */
export function ctxPrimitive(n: number, content: Buffer | string): Buffer {
  return tlv(0x80 | n, Buffer.isBuffer(content) ? content : Buffer.from(content));
}

/** AlgorithmIdentifier for Ed25519 (RFC 8410: parameters MUST be absent). */
export function ed25519AlgId(): Buffer {
  return seq(oid('1.3.101.112'));
}

/** SubjectPublicKeyInfo for an Ed25519 raw public key (32 bytes). */
export function ed25519Spki(rawPub: Buffer): Buffer {
  return seq(ed25519AlgId(), bitString(rawPub));
}

// EctunServer: the reverse proxy that terminates encrypted tunnels and forwards
// logical streams to local upstreams according to the routing table.

import * as tls from 'node:tls';
import type { TLSSocket } from 'node:tls';
import * as net from 'node:net';
import { randomBytes } from 'node:crypto';
import { MuxSession } from './mux.js';
import type { TunnelStream } from './stream.js';
import { serverTlsOptions, authorizePeer, compileAuth, type AuthConfig, type CompiledAuth } from './tlsctx.js';
import { compileRoutes } from './router.js';
import type { RouteConfig, ClientTargetsConfig, UpstreamInput } from './router.js';
import { normalizeFingerprint } from './keys.js';
import type { Identity } from './keys.js';
import { parseTarget, fmtBytes, type Logger } from './util.js';

/** Server-wide counters. */
export interface ServerStats {
  startedAt: number | null;
  connectionsTotal: number;
  connectionsActive: number;
  connectionsRejected: number;
  streamsTotal: number;
  streamsActive: number;
  upstreamBytes: number;
  activeStreams: number;
}

/** createProxyServer() options (mirrors the Node SDK; wsIdentity is not ported). */
export interface ProxyServerOptions {
  listen?: string | [string, number];
  /** {certPem, keyPem, fingerprint} from loadIdentity/generateIdentity. */
  identity: { certPem: string; keyPem: string; fingerprint?: string };
  auth?: AuthConfig;
  routes?: RouteConfig[];
  fallbackUpstream?: UpstreamInput;
  clientTargets?: ClientTargetsConfig | boolean | null;
  maxDataFrame?: number;
  rxWindow?: number;
  rxWindowMax?: number;
  maxStreams?: number;
  keepaliveSec?: number;
  connectTimeoutMs?: number;
  log?: Logger | null;
}

/** A running tunnel server handle. */
export interface ProxyServer {
  start(): Promise<net.AddressInfo | string>;
  stop(): Promise<void>;
  /** Update the whitelist at runtime; rotates TLS ticket keys. */
  setAuth(nextAuthCfg: AuthConfig): void;
  setRoutes(next: { routes?: RouteConfig[]; fallbackUpstream?: UpstreamInput; clientTargets?: ClientTargetsConfig | null }): void;
  address(): net.AddressInfo | string | null;
  readonly stats: ServerStats;
}

/**
 * Create the tunnel server: a TLS 1.3 listener that authorizes clients by
 * Ed25519 fingerprint, multiplexes their streams (MuxSession), and routes each
 * stream to a local upstream. Returns {start, stop, setAuth, setRoutes,
 * address, stats}.
 */
export function createProxyServer({
  listen = '127.0.0.1:0',
  identity,
  auth: authCfg = { mode: 'whitelist', fingerprints: [] },
  routes = [],
  fallbackUpstream = null,
  clientTargets = null,
  maxDataFrame,
  rxWindow,
  rxWindowMax,
  maxStreams,
  keepaliveSec = 30,
  connectTimeoutMs = 5000,
  log,
}: ProxyServerOptions): ProxyServer {
  if (!identity?.certPem || !identity?.keyPem) throw new Error('server identity required');

  const logger: Logger = log ?? { info() {}, warn() {}, error() {}, debug() {} };
  let auth: CompiledAuth = compileAuth(authCfg, normalizeFingerprint);
  let router = compileRoutes({ routes, fallbackUpstream, clientTargets });

  const stats: Omit<ServerStats, 'activeStreams'> = {
    startedAt: null,
    connectionsTotal: 0,
    connectionsActive: 0,
    connectionsRejected: 0,
    streamsTotal: 0,
    streamsActive: 0,
    upstreamBytes: 0,
  };

  function startSession(socket: TLSSocket, who: string): void {
    stats.connectionsTotal++;
    stats.connectionsActive++;
    logger.info('client connected', { peer: socket.remoteAddress ?? '?', fp: who });

    const session = new MuxSession(socket, {
      isClient: false,
      name: identity.fingerprint?.slice(7, 19) ?? 'server',
      log: logger,
      maxDataFrame, rxWindow, rxWindowMax, maxStreams, keepaliveSec,
    });
    session.on('stream', (stream: TunnelStream, target: { host?: string | null; port?: number; unix?: string | null }) =>
      handleStream(stream, target, who));
    session.on('close', (reason: unknown) => {
      stats.connectionsActive--;
      logger.info('client disconnected', { peer: socket.remoteAddress ?? '?', fp: who, reason: String(reason).slice(0, 80) });
    });
    socket.on('error', () => { /* already routed through mux failure */ });
  }

  const tlsServer = tls.createServer(
    serverTlsOptions({ cert: identity.certPem, key: identity.keyPem }),
    (tlsSocket) => {
      const peer = tlsSocket.remoteAddress ?? '?';
      const verdict = authorizePeer(tlsSocket, auth);
      if (verdict.ok) {
        const who = (verdict.fingerprint ?? '').slice('sha256:'.length).slice(0, 12);
        startSession(tlsSocket, who);
        return;
      }
      stats.connectionsRejected++;
      logger.warn('rejected connection', { peer, reason: verdict.reason });
      tlsSocket.destroy();
    },
  );
  tlsServer.on('tlsClientError', (err: Error, sock: net.Socket) => {
    stats.connectionsRejected++;
    logger.debug('tls client error', { message: String(err?.message).slice(0, 80), peer: sock?.remoteAddress });
  });

  function handleStream(stream: TunnelStream, target: { host?: string | null; port?: number; unix?: string | null }, who: string): void {
    stats.streamsTotal++;
    const decision = router.resolve(target);
    const where = target?.unix
      ? `unix:${target.unix}`
      : `${target?.host ?? '?'}:${target?.port ?? 0}`;

    if (decision.action === 'deny') {
      logger.warn('stream denied', { who, target: where, reason: decision.reason });
      stream.reject('denied', decision.reason);
      return;
    }

    const upstreamAddr = decision.action === 'route' ? decision.upstream : decision.target;
    const label = upstreamAddr?.unix ? `unix:${upstreamAddr.unix}` : `${upstreamAddr?.host}:${upstreamAddr?.port}`;

    const upstream = upstreamAddr?.unix
      ? net.connect({ path: upstreamAddr.unix })
      : net.connect({ host: upstreamAddr?.host, port: Number(upstreamAddr?.port) });

    let settled = false;
    const dialTimer = setTimeout(() => {
      if (!settled) upstream.destroy();
    }, connectTimeoutMs);

    upstream.on('connect', () => {
      settled = true;
      clearTimeout(dialTimer);
      stats.streamsActive++;
      stream.accept({ upstream: label });
      logger.debug('stream open', { who, target: where, upstream: label });

      pump(stream, upstream, () => {
        stats.streamsActive--;
      });
    });

    upstream.on('error', (err: Error & { code?: string }) => {
      clearTimeout(dialTimer);
      if (!settled) {
        logger.info('upstream unreachable', { who, target: where, upstream: label, message: err.message });
        stream.reject('unreachable', `dial ${label}: ${err.code ?? err.message}`);
      } else {
        stream.abort(1, `upstream error: ${err.code ?? err.message}`);
      }
    });

    stream.on('aborted', (reason: unknown) => {
      logger.debug('stream aborted by peer', { who, target: where, reason: String(reason).slice(0, 60) });
      upstream.destroy();
    });
  }

  function pump(stream: TunnelStream, upstream: net.Socket, onDone: () => void): void {
    let bytesUp = 0;   // client -> upstream
    let bytesDown = 0; // upstream -> client
    let upstreamEnded = false;
    let finished = false;
    const t0 = Date.now();

    stream.on('data', (c: Buffer) => {
      bytesUp += c.length;
    });
    upstream.on('data', (c: Buffer) => {
      bytesDown += c.length;
    });

    const finish = () => {
      if (finished) return; // both sides closing must not double-count
      finished = true;
      stats.upstreamBytes += bytesUp + bytesDown;
      onDone();
      logger.debug('stream closed', {
        ms: Date.now() - t0,
        up: fmtBytes(bytesUp),
        down: fmtBytes(bytesDown),
      });
    };
    stream.on('close', () => {
      upstream.destroy();
      finish();
    });
    upstream.on('end', () => {
      upstreamEnded = true; // pipe() sends FIN after queued data
    });
    upstream.on('close', () => {
      // abort only on premature close (RST-ish); graceful ends flush via pipe+end()
      if (!upstreamEnded && !stream.writableEnded && !stream.destroyed) {
        stream.abort(0, 'upstream closed');
      }
      finish();
    });
    // errors on either side tear both down
    stream.on('error', () => upstream.destroy());
    upstream.on('error', () => stream.destroy());

    upstream.pipe(stream);
    stream.pipe(upstream);
  }

  return {
    async start(): Promise<net.AddressInfo | string> {
      const t = parseTarget(listen, 0);
      await new Promise<void>((resolve, reject) => {
        tlsServer.once('error', reject);
        tlsServer.listen(t.port, t.host, () => {
          stats.startedAt = Date.now();
          const addr = tlsServer.address();
          logger.info('krymux server listening', {
            host: typeof addr === 'object' && addr ? addr.address : '?',
            port: typeof addr === 'object' && addr ? addr.port : 0,
            auth: auth.mode,
            clients: auth.fingerprints.size,
            routes: router.routes.length + (router.fallback ? '+fallback' : ''),
          });
          resolve();
        });
      });
      return tlsServer.address() as net.AddressInfo | string;
    },
    async stop(): Promise<void> {
      await new Promise<void>((resolve) => tlsServer.close(() => resolve()));
      for (const s of (tlsServer as tls.Server & { clients?: Set<net.Socket> }).clients ?? []) s.destroy();
    },
    /** Update the whitelist at runtime; rotates TLS ticket keys so revoked
     *  clients cannot ride existing session tickets. */
    setAuth(nextAuthCfg: AuthConfig): void {
      auth = compileAuth(nextAuthCfg, normalizeFingerprint);
      // tls.Server exposes setTicketKeys on Node >= 20? rotate defensively:
      try {
        (tlsServer as unknown as { setTicketKeys?: (k: Buffer) => void }).setTicketKeys?.(randomBytes(48));
      } catch {
        /* not supported */
      }
      logger.info('auth updated', { mode: auth.mode, clients: auth.fingerprints.size });
    },
    setRoutes(next: { routes?: RouteConfig[]; fallbackUpstream?: UpstreamInput; clientTargets?: ClientTargetsConfig | null }): void {
      router = compileRoutes(next);
    },
    address(): net.AddressInfo | string | null {
      return tlsServer.address();
    },
    get stats(): ServerStats {
      return { ...stats, activeStreams: stats.streamsActive };
    },
  };
}

/** Alias kept for discoverability — same as createProxyServer. */
export const createServer = createProxyServer;

// MuxSession: multiplexes many TunnelStreams over one ordered byte pipe
// (in production a TLS 1.3 socket; in tests a duplexPair).
//
// Handshake: both sides immediately send a HELLO frame (JSON) describing limits and
// supported compression. Effective per-direction data-frame cap and initial stream
// windows derive from the *peer's* HELLO. Streams are client-odd / server-even.

import { EventEmitter } from 'node:events';
import { Buffer } from 'node:buffer';
import type { Duplex } from 'node:stream';
import {
  encodeFrame, FrameParser, FT, CLOSE_CODES, ProtocolError,
  DEFAULT_MAX_DATA, MAX_HELLO, MAX_OPEN, MAX_CONTROL, HARD_MAX_FRAME,
  type ParsedFrame,
} from './frame.js';
import { TunnelStream } from './stream.js';
import { supportedAlgorithms, negotiate, parseLevel } from './compress.js';
import { nowMs, randomId, type Logger } from './util.js';

const PROTO_VERSION = 1;
const DEFAULT_WINDOW = 262144;
const DEFAULT_MAX_STREAMS = 1024;
const OPEN_ACK_TIMEOUT = 12000;

function clamp(v: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, Number(v) || 0));
}

/** Session-wide counters. */
export interface MuxStats {
  startedAt: number;
  framesRx: number;
  framesTx: number;
  wireBytesRx: number;
  wireBytesTx: number;
  streamsOpened: number;
  rttMs: number | null;
}

/** MuxSession constructor options. */
export interface MuxOptions {
  isClient?: boolean;
  name?: string;
  log?: Logger | null;
  maxDataFrame?: number;
  rxWindow?: number;
  rxWindowMax?: number;
  maxStreams?: number;
  keepaliveSec?: number;
  helloTimeoutMs?: number;
}

/** Options for openStream(). */
export interface OpenStreamOptions {
  host?: string | null;
  port?: number;
  unix?: string | null;
  compression?: string;
  hint?: string;
  meta?: unknown;
}

interface PingEntry {
  t0: number;
  resolve: (rtt: number) => void;
  reject: (e: Error) => void;
  timer: NodeJS.Timeout;
}

/**
 * Multiplexes many TunnelStreams over one ordered, reliable byte pipe
 * (a TLS 1.3 socket in production, a duplexPair in tests). Speaks the Krymux
 * wire protocol: HELLO handshake, OPEN/OPEN_ACK stream setup, credit-windowed
 * DATA with optional per-stream compression, WINDOW flow control, CLOSE,
 * PING/PONG keepalive, and GOAWAY shutdown.
 */
export class MuxSession extends EventEmitter {
  readonly socket: Duplex;
  readonly isClient: boolean;
  readonly name: string;
  readonly log: Logger | null;

  readonly ourMaxDataFrame: number;
  readonly rxWindow: number;
  readonly rxWindowMax: number;
  readonly maxStreams: number;
  readonly keepaliveMs: number;

  private _ourSupported: string[] | null = null; // resolved at HELLO time
  private _peerSupported: string[] | null = null;
  private _peerMaxDataFrame = DEFAULT_MAX_DATA;
  private _peerWindow = DEFAULT_WINDOW;
  private _peerName = '';

  private _streams = new Map<number, TunnelStream>();
  private _nextId: number;
  private readonly _parser: FrameParser;
  private _helloSeen = false;
  private _gone = false;
  private _closeEmitted = false;
  private _drainPromise: Promise<void> | null = null;
  private _drainResolve: (() => void) | null = null;
  private _keepaliveTimer: NodeJS.Timeout | null = null;
  private _pings = new Map<string, PingEntry>();
  private _helloTimer: NodeJS.Timeout;
  private _helloSentPromise: Promise<void> | null = null;
  private readonly _readyPromise: Promise<void>;
  private _readyResolve!: () => void;
  private _readyReject!: (e: Error) => void;

  readonly stats: MuxStats = {
    startedAt: Date.now(),
    framesRx: 0, framesTx: 0,
    wireBytesRx: 0, wireBytesTx: 0,
    streamsOpened: 0,
    rttMs: null,
  };

  constructor(socket: Duplex, opts: MuxOptions = {}) {
    super();
    const {
      isClient = false,
      name = '',
      log = null,
      maxDataFrame = DEFAULT_MAX_DATA,
      rxWindow = DEFAULT_WINDOW,
      rxWindowMax = 4194304,
      maxStreams = DEFAULT_MAX_STREAMS,
      keepaliveSec = 30,
      helloTimeoutMs = 10000,
    } = opts;

    this.socket = socket;
    this.isClient = isClient;
    this.name = name;
    this.log = log;

    this.ourMaxDataFrame = clamp(maxDataFrame, 1024, HARD_MAX_FRAME);
    this.rxWindow = clamp(rxWindow, 16384, 16 * 1024 * 1024);
    this.rxWindowMax = clamp(rxWindowMax, this.rxWindow, 64 * 1024 * 1024);
    this.maxStreams = clamp(maxStreams, 1, 65535);
    this.keepaliveMs = clamp(keepaliveSec, 0, 600) * 1000;

    this._nextId = isClient ? 1 : 2;
    this._parser = new FrameParser((f) => this._onFrame(f), { maxFrame: HARD_MAX_FRAME });

    this._readyPromise = new Promise((resolve, reject) => {
      this._readyResolve = resolve;
      this._readyReject = reject;
    });
    this._helloTimer = setTimeout(() => {
      this._fail(new ProtocolError('peer did not send HELLO in time', CLOSE_CODES.PROTO));
    }, helloTimeoutMs);
    this._helloTimer.unref?.();

    socket.on('data', (chunk: Buffer) => {
      this.stats.wireBytesRx += chunk.length;
      try {
        this._parser.push(chunk);
      } catch (err) {
        this._failProtocol(err as Error);
      }
    });
    socket.on('error', (err: Error) => this._fail(err));
    socket.on('close', () => this._fail(new Error('underlying socket closed')));
    socket.on('end', () => this._fail(new Error('peer closed connection (FIN)')));
    socket.on('drain', () => this._onDrain());

    this.helloSent().catch(() => { /* surfaced via _fail */ });
  }

  get peerMaxDataFrame(): number {
    return this._peerMaxDataFrame;
  }

  get peerName(): string {
    return this._peerName;
  }

  get streamCount(): number {
    return this._streams.size;
  }

  /** Resolves once the peer's HELLO has been received and validated. */
  ready(): Promise<void> {
    return this._readyPromise;
  }

  /** Resolves once OUR HELLO has actually been written to the socket. */
  helloSent(): Promise<void> {
    this._helloSentPromise ??= this._sendHello();
    return this._helloSentPromise;
  }

  // ---------------- lifecycle ----------------

  private async _sendHello(): Promise<void> {
    this._ourSupported = await supportedAlgorithms();
    if (this._gone) return;
    const payload = Buffer.from(JSON.stringify({
      v: PROTO_VERSION,
      mode: this.isClient ? 'client' : 'server',
      name: this.name,
      maxDataFrame: this.ourMaxDataFrame,
      rxWindow: this.rxWindow,
      maxStreams: this.maxStreams,
      compression: this._ourSupported,
    }), 'utf8');
    this._sendControl(FT.HELLO, 0, payload);
  }

  /** Graceful shutdown: send GOAWAY, tear down all streams, end the socket. */
  close(reason = 'going away'): void {
    if (this._gone) return;
    this._gone = true;
    this._closeEmitted = true; // prevent _fail from emitting 'close' again
    try {
      this._sendControl(FT.GOAWAY, 0, Buffer.from(JSON.stringify({ reason }), 'utf8'));
    } catch {
      /* socket may already be gone */
    }
    this._teardownStreams(new Error(`session closed: ${reason}`));
    this.socket.end();
    setTimeout(() => this.socket.destroy(), 2000).unref?.();
    this._stopKeepalive();
    this.emit('close', reason);
  }

  private _fail(err: Error): void {
    if (this._gone && this._closeEmitted) return;
    this._gone = true;
    clearTimeout(this._helloTimer);
    this._stopKeepalive();
    this._teardownStreams(err);
    for (const p of this._pings.values()) p.reject(err);
    this._pings.clear();
    this._readyReject?.(err);
    this.socket.destroy();
    if (!this._closeEmitted) {
      this._closeEmitted = true;
      this.emit('close', err?.message ?? String(err));
      if (this.listenerCount('error') > 0) this.emit('error', err);
    }
  }

  private _failProtocol(err: Error): void {
    // Attempt a best-effort GOAWAY so the peer knows why we dropped them.
    if (!this._gone) {
      try {
        this._sendControl(FT.GOAWAY, 0, Buffer.from(JSON.stringify({
          reason: `protocol error: ${err.message}`,
        }), 'utf8'));
      } catch {
        /* ignore */
      }
    }
    this._fail(err);
  }

  private _teardownStreams(err: Error): void {
    const list = [...this._streams.values()];
    this._streams.clear();
    for (const s of list) {
      try {
        s._destroySilent(err?.message ?? 'session closed');
      } catch {
        /* ignore */
      }
    }
  }

  private _stopKeepalive(): void {
    if (this._keepaliveTimer) {
      clearInterval(this._keepaliveTimer);
      this._keepaliveTimer = null;
    }
  }

  // ---------------- writing ----------------

  _sendControl(type: number, sid: number, payload: Buffer | null): void {
    if (this._gone && type !== FT.GOAWAY) return;
    const frame = encodeFrame(type, 0, sid, payload ?? null);
    this.stats.framesTx++;
    this.stats.wireBytesTx += frame.length;
    this.socket.write(frame);
  }

  /**
   * Write a DATA frame on behalf of a stream. Returns (a promise for) true when
   * written; if the socket is backpressured, waits for drain and then returns true.
   * Order relative to other frames is preserved by the single socket.
   */
  async _writeData(_stream: TunnelStream, frame: Buffer): Promise<boolean> {
    this.stats.framesTx++;
    this.stats.wireBytesTx += frame.length;
    const ok = this.socket.write(frame);
    if (ok) return true;
    if (!this._drainPromise) {
      this._drainPromise = new Promise((resolve) => {
        this._drainResolve = resolve;
      });
    }
    await this._drainPromise;
    return true;
  }

  private _onDrain(): void {
    const resolve = this._drainResolve;
    this._drainPromise = null;
    this._drainResolve = null;
    if (resolve) resolve();
    for (const s of this._streams.values()) s._pump();
  }

  // ---------------- reading ----------------

  private _onFrame({ type, flags, streamId, payload }: ParsedFrame): void {
    this.stats.framesRx++;
    if (!this._helloSeen && type !== FT.HELLO) {
      throw new ProtocolError(`frame type ${type} before HELLO`);
    }
    switch (type) {
      case FT.HELLO: return this._onHello(payload);
      case FT.OPEN: return this._onOpen(streamId, payload);
      case FT.OPEN_ACK: return this._onOpenAck(streamId, payload);
      case FT.DATA: return this._onData(streamId, flags, payload);
      case FT.WINDOW: return this._onWindow(streamId, payload);
      case FT.CLOSE: return this._onClose(streamId, payload);
      case FT.PING:
        // reply only after our own HELLO is on the wire (a peer may ping
        // before its HELLO reached us; our HELLO must still go out first)
        this.helloSent().then(() => {
          if (!this._gone) this._sendControl(FT.PONG, 0, payload);
        }).catch(() => {});
        return;
      case FT.PONG: return this._onPong(payload);
      case FT.GOAWAY: return this._fail(new Error(`peer sent GOAWAY: ${payload?.toString('utf8') ?? ''}`));
      default: throw new ProtocolError(`unknown frame type ${type}`);
    }
  }

  private _onHello(payload: Buffer | null): void {
    if (this._helloSeen) throw new ProtocolError('duplicate HELLO');
    if (!payload || payload.length === 0 || payload.length > MAX_HELLO) {
      throw new ProtocolError('bad HELLO size');
    }
    let hello: any;
    try {
      hello = JSON.parse(payload.toString('utf8'));
    } catch {
      throw new ProtocolError('bad HELLO json');
    }
    if (hello.v !== PROTO_VERSION) throw new ProtocolError(`unsupported protocol version ${hello.v}`);
    this._helloSeen = true;
    clearTimeout(this._helloTimer);
    this._peerSupported = Array.isArray(hello.compression) ? hello.compression : ['none'];
    this._peerMaxDataFrame = clamp(hello.maxDataFrame ?? DEFAULT_MAX_DATA, 1024, HARD_MAX_FRAME);
    this._peerWindow = clamp(hello.rxWindow ?? DEFAULT_WINDOW, 16384, 16 * 1024 * 1024);
    this._peerName = String(hello.name ?? '');
    if (this.keepaliveMs > 0) {
      this._keepaliveTimer = setInterval(() => this._pingTick(), this.keepaliveMs);
      this._keepaliveTimer.unref?.();
    }
    this._readyResolve();
    this.emit('ready');
  }

  private _onOpen(sid: number, payload: Buffer | null): void {
    if (this.isClient) throw new ProtocolError('client received OPEN');
    if (!payload || payload.length === 0 || payload.length > MAX_OPEN) {
      throw new ProtocolError('bad OPEN size');
    }
    // client-initiated streams use odd ids; even (or 0) is a protocol error
    if (sid === 0 || (sid & 1) === 0) throw new ProtocolError(`bad stream id in OPEN: ${sid}`);
    if (this._streams.has(sid)) throw new ProtocolError(`stream ${sid} already exists`);
    if (this._streams.size >= this.maxStreams) {
      this._sendControl(FT.OPEN_ACK, sid, Buffer.from(JSON.stringify({
        ok: false, code: 'maxstreams', reason: `limit ${this.maxStreams}`,
      }), 'utf8'));
      return;
    }
    let target: any;
    try {
      target = JSON.parse(payload.toString('utf8'));
    } catch {
      throw new ProtocolError('bad OPEN json');
    }

    const algo = negotiate(target.compression || 'auto', this._ourSupported ?? ['none']);
    const stream = new TunnelStream(this, sid, {
      initiator: false,
      target,
      txWindow: this._peerWindow,
      rxWindow: this.rxWindow,
      rxWindowMax: this.rxWindowMax,
    });
    stream.compression = algo;
    this._streams.set(sid, stream);
    this.stats.streamsOpened++;

    if (this.listenerCount('stream') === 0) {
      stream.reject('nohandler', 'server has no stream handler');
      return;
    }
    this.emit('stream', stream, { ...target, compression: algo });
  }

  private _onOpenAck(sid: number, payload: Buffer | null): void {
    const stream = this._streams.get(sid);
    if (!stream || !stream.initiator) return;
    if (payload && payload.length > MAX_CONTROL + 4096) throw new ProtocolError('bad OPEN_ACK size');
    let ack: any = {};
    try {
      ack = payload ? JSON.parse(payload.toString('utf8')) : {};
    } catch {
      /* treat as rejection */
    }
    if (ack.ok) {
      if (typeof ack.compression === 'string' && stream.compression === 'none') {
        stream.compression = ack.compression;
      }
      stream._settleAck(null, ack);
    } else {
      const err: Error & { code?: string } = new Error(`open rejected: ${ack.code ?? 'denied'} ${ack.reason ?? ''}`.trim());
      err.code = ack.code;
      this._streams.delete(sid);
      stream._settleAck(err);
      stream._destroyLocal(null); // error already surfaced through the ack promise
    }
  }

  private _onData(sid: number, flags: number, payload: Buffer | null): void {
    const stream = this._streams.get(sid);
    if (!stream) return; // unknown/already-closed stream — ignore, bounded by one frame
    if (payload && payload.length > this.rxWindow + HARD_MAX_FRAME) {
      throw new ProtocolError('DATA exceeds window bounds');
    }
    stream.deliver(payload, flags);
  }

  private _onWindow(sid: number, payload: Buffer | null): void {
    const stream = this._streams.get(sid);
    if (!stream) return;
    if (!payload || payload.length !== 4) throw new ProtocolError('bad WINDOW frame');
    const delta = payload.readUInt32BE(0);
    if (delta === 0 || delta > 64 * 1024 * 1024) throw new ProtocolError(`bad WINDOW delta ${delta}`);
    stream.addCredit(delta);
  }

  private _onClose(sid: number, payload: Buffer | null): void {
    const stream = this._streams.get(sid);
    if (!stream) return;
    const code = payload && payload.length > 0 ? payload[0]! : CLOSE_CODES.CANCEL;
    const reason = payload && payload.length > 1 ? payload.subarray(1).toString('utf8') : '';
    stream.peerClosed(code, reason);
  }

  private _onPong(payload: Buffer | null): void {
    if (!payload || payload.length < 16) return;
    const nonce = payload.subarray(0, 16).toString('hex');
    const entry = this._pings.get(nonce);
    if (!entry) return;
    this._pings.delete(nonce);
    clearTimeout(entry.timer);
    const rtt = nowMs() - entry.t0;
    this.stats.rttMs = this.stats.rttMs == null ? rtt : Math.round(this.stats.rttMs * 0.7 + rtt * 0.3);
    entry.resolve(rtt);
  }

  // ---------------- client API ----------------

  /**
   * Open a new outgoing stream (client role; ids are odd).
   * Resolves with the TunnelStream once the peer's OPEN_ACK arrives.
   * `target` ({host, port} or {unix}) is advisory metadata the server routes on.
   */
  async openStream(
    { host = null, port = 0, unix = null, compression = 'auto', hint = 'raw', meta = undefined }: OpenStreamOptions = {},
  ): Promise<TunnelStream> {
    await this.ready();
    await this.helloSent(); // never send frames before our own HELLO is on the wire
    if (this._gone) throw new Error('session is gone');
    if (this._streams.size >= this.maxStreams) {
      const e: Error & { code?: string } = new Error(`max streams reached (${this.maxStreams})`);
      e.code = 'maxstreams';
      throw e;
    }
    const sid = this._nextId;
    this._nextId += 2;

    const algo = negotiate(compression, this._peerSupported ?? ['none']);
    const stream = new TunnelStream(this, sid, {
      initiator: true,
      target: { host, port, unix, hint, meta },
      txWindow: this._peerWindow,
      rxWindow: this.rxWindow,
      rxWindowMax: this.rxWindowMax,
    });
    stream.compression = algo;
    stream.compressionLevel = parseLevel(compression);
    this._streams.set(sid, stream);
    this.stats.streamsOpened++;

    const openPayload = Buffer.from(JSON.stringify({
      host, port, unix, hint, meta,
      compression: algo,
    }), 'utf8');
    this._sendControl(FT.OPEN, sid, openPayload);

    // The ack may already have settled (synchronous transports deliver in-tick).
    try {
      await Promise.race([
        stream._waitAck(),
        new Promise<never>((_, reject) => {
          const t = setTimeout(() => {
            const e: Error & { code?: string } = new Error('open stream timeout');
            e.code = 'timeout';
            reject(e);
          }, OPEN_ACK_TIMEOUT);
          t.unref?.();
        }),
      ]);
    } catch (err) {
      this._streams.delete(sid);
      stream._destroyLocal(null); // error surfaced through this rejection
      throw err;
    }
    return stream;
  }

  // ---------------- keepalive ----------------

  private _pingTick(): void {
    this.ping().catch(() => { /* failures surface via socket close */ });
  }

  /** Round-trip latency probe; resolves to the RTT in milliseconds. */
  ping(): Promise<number> {
    if (this._gone) return Promise.reject(new Error('session is gone'));
    const nonce = randomId(16);
    const buf = Buffer.from(nonce, 'hex');
    const t0 = nowMs();
    return new Promise((resolve, reject) => {
      const entry: PingEntry = { t0, resolve, reject, timer: null as unknown as NodeJS.Timeout };
      entry.timer = setTimeout(() => {
        this._pings.delete(nonce);
        reject(new Error('ping timeout'));
      }, Math.max(5000, (this.keepaliveMs || 10000) * 2));
      entry.timer.unref?.();
      this._pings.set(nonce, entry);
      this._sendControl(FT.PING, 0, buf);
    });
  }

  _unmapStream(stream: TunnelStream): void {
    if (this._streams.get(stream.id) === stream) {
      this._streams.delete(stream.id);
    }
  }
}

// Wire framing: [type:1][flags:1][streamId:4][length:4][payload:length] — all big-endian.
// Byte-for-byte compatible with the Rust (crates/krymux/src/frame.rs) and Node
// (ectun/lib/frame.mjs) implementations of the Krymux protocol.

import { Buffer } from 'node:buffer';

export const FT = Object.freeze({
  HELLO: 1,     // sid=0, both sides, JSON
  OPEN: 2,      // open a stream, JSON target descriptor
  OPEN_ACK: 3,  // accept/reject result, JSON
  DATA: 4,      // payload (maybe compressed; FLAG.FIN marks end-of-stream)
  WINDOW: 5,    // 4-byte BE credit delta
  CLOSE: 6,     // abort/teardown: [code:1][reason:utf8]
  PING: 7,      // sid=0, opaque echo payload
  PONG: 8,      // sid=0, echo of PING
  GOAWAY: 9,    // sid=0, connection-level shutdown, JSON reason
} as const);

export const FLAG = Object.freeze({
  COMPRESSED: 0x01,
  FIN: 0x02,
} as const);

export const CLOSE_CODES = Object.freeze({
  EOS: 0,          // clean end (all data delivered)
  ERROR: 1,        // unexpected error
  REFUSED: 2,      // target refused by policy
  UNREACHABLE: 3,  // upstream dial failed
  GOAWAY: 4,       // connection is going away
  CANCEL: 5,       // caller aborted
  MAX_STREAMS: 6,  // stream limit reached
  PROTO: 7,        // protocol violation
  DENIED: 8,       // auth denied
} as const);

export const HEADER_SIZE = 10;
export const HARD_MAX_FRAME = 1 << 20;      // absolute cap for any frame payload
export const DEFAULT_MAX_DATA = 64 * 1024;  // default max DATA payload
export const MAX_HELLO = 8 * 1024;
export const MAX_OPEN = 8 * 1024;
export const MAX_CONTROL = 1024;            // OPEN_ACK / GOAWAY / CLOSE reason

/** Framing-layer violation; `code` is one of CLOSE_CODES (default PROTO). */
export class ProtocolError extends Error {
  code: number;

  constructor(message: string, code: number = CLOSE_CODES.PROTO) {
    super(message);
    this.name = 'ProtocolError';
    this.code = code;
  }
}

/** One parsed frame handed to the FrameParser callback. */
export interface ParsedFrame {
  type: number;
  flags: number;
  streamId: number;
  payload: Buffer | null;
}

export type FrameCallback = (frame: ParsedFrame) => void;

/** Build a single Buffer frame. */
export function encodeFrame(
  type: number,
  flags: number,
  streamId: number,
  payload: Buffer | null = null,
): Buffer {
  const len = payload ? payload.length : 0;
  if (len > HARD_MAX_FRAME) throw new ProtocolError(`frame payload too large: ${len}`);
  const buf = Buffer.allocUnsafe(HEADER_SIZE + len);
  buf[0] = type;
  buf[1] = flags & 0xff;
  buf.writeUInt32BE(streamId >>> 0, 2);
  buf.writeUInt32BE(len, 6);
  if (len && payload) payload.copy(buf, HEADER_SIZE);
  return buf;
}

/**
 * Incremental frame parser. onFrame({type, flags, streamId, payload}).
 * Throws ProtocolError on oversize/invalid frames — caller must drop the connection.
 */
export class FrameParser {
  private readonly _onFrame: FrameCallback;
  private readonly _maxFrame: number;
  private _buf: Buffer | null = null; // accumulated remainder
  private _count = 0;

  constructor(onFrame: FrameCallback, { maxFrame = HARD_MAX_FRAME }: { maxFrame?: number } = {}) {
    this._onFrame = onFrame;
    this._maxFrame = maxFrame;
  }

  get framesParsed(): number {
    return this._count;
  }

  push(chunk: Buffer): void {
    let buf: Buffer = this._buf ? Buffer.concat([this._buf, chunk]) : chunk;
    this._buf = null;
    for (;;) {
      if (buf.length < HEADER_SIZE) break;
      const type = buf[0];
      const flags = buf[1];
      const streamId = buf.readUInt32BE(2);
      const len = buf.readUInt32BE(6);
      if (type < FT.HELLO || type > FT.GOAWAY) {
        throw new ProtocolError(`unknown frame type: ${type}`);
      }
      if (len > this._maxFrame) {
        throw new ProtocolError(`frame length ${len} exceeds cap ${this._maxFrame}`);
      }
      const total = HEADER_SIZE + len;
      if (buf.length < total) break;
      const payload = len > 0 ? Buffer.from(buf.subarray(HEADER_SIZE, total)) : null;
      this._count++;
      this._onFrame({ type, flags, streamId, payload });
      buf = buf.subarray(total);
      if (buf.length === 0) break;
    }
    this._buf = buf.length ? buf : null;
  }
}

// TunnelStream: one logical full-duplex byte stream inside a MuxSession.
//
// - Write path: app chunk -> (optional) continuous-context compression -> one or more
//   DATA frames, gated by a credit window (initially granted by the peer's HELLO,
//   replenished by WINDOW frames). Credits are accounted in *decompressed* bytes.
// - Read path: mux deliver() -> (optional) decompression -> readable side; consumption
//   is reported back with batched WINDOW frames.
// - Half-close: stream.end() sends a FIN flag on the last frame; receiving FIN ends
//   the readable side only. CLOSE aborts both directions.

import { Duplex } from 'node:stream';
import { Buffer } from 'node:buffer';
import { encodeFrame, FT, FLAG, CLOSE_CODES } from './frame.js';
import {
  createCompressContext, createDecompressContext, looksPrecompressed,
  ALGO_NONE, type CompCtx,
} from './compress.js';
import { Batch } from './util.js';
import type { MuxSession } from './mux.js';

/** Stream target descriptor ({host, port} or {unix}); advisory routing metadata. */
export interface StreamTarget {
  host?: string | null;
  port?: number;
  unix?: string | null;
  hint?: string;
  compression?: string;
  meta?: unknown;
}

/** Per-stream counters. */
export interface StreamStats {
  bytesTx: number;
  bytesRx: number;
  framesTx: number;
  framesRx: number;
  startedAt: number;
}

/** One queued write: a compressed chunk (possibly split across frames) or a bare FIN. */
interface SendItem {
  wire: Buffer;
  logical: number;
  cbs: Array<(err?: Error | null) => void>;
  fin: boolean;
  off: number;
  charged: number;
}

/**
 * One logical full-duplex byte stream inside a MuxSession — a Node Duplex.
 * Client code normally obtains these from MuxSession.openStream() (initiator)
 * or the session's 'stream' event (responder, which must accept()/reject()).
 */
export class TunnelStream extends Duplex {
  readonly mux: MuxSession;
  readonly id: number;
  readonly initiator: boolean;
  target: StreamTarget | null;
  compression: string = ALGO_NONE;
  compressionLevel: number | null = null; // parsed from 'deflate:9'-style requests

  txWindow: number; // credits we may still spend (decompressed bytes)
  abortedReason?: string;

  private _comp: CompCtx | null = null;
  private _decomp: CompCtx | null = null;
  private _sniffed = false;

  private _sendQ: SendItem[] = []; // [{wire, logical, cbs[], fin, off}]
  private _pumping = false;
  private _deliverChain: Promise<unknown> = Promise.resolve();

  private _pendingRx: Array<Buffer | null> = []; // buffered inbound when the readable buffer is full
  private _eofPushed = false;
  private _finReceived = false;
  private _finSent = false;
  private _closeSent = false;
  private _destroying = false;
  private _ackDone = false;

  // receiver-side dynamic right-sizing (TCP-style): when the app keeps up with
  // everything granted, grow the peer's window multiplicatively up to rxWindowMax.
  private _rxGranted: number;
  private _rxWindowMax: number;
  private _consumedSinceGrow = 0;
  private _growAt = Date.now();
  private _growRetryTimer: NodeJS.Timeout | null = null;
  private _rxRetryTimer: NodeJS.Timeout | null = null;

  private readonly _creditBatch: Batch;

  readonly stats: StreamStats = { bytesTx: 0, bytesRx: 0, framesTx: 0, framesRx: 0, startedAt: Date.now() };

  // OPEN_ACK plumbing (settle-once, order-independent: an ack may legally arrive
  // before the opener attaches its waiters when the transport delivers synchronously)
  private _ackSettled = false;
  private _ackValue: unknown = null;
  private _ackErr: Error | null = null;
  private _ackResolve: ((s: TunnelStream) => void) | null = null;
  private _ackReject: ((e: Error) => void) | null = null;

  constructor(
    mux: MuxSession,
    id: number,
    {
      initiator = false,
      target = null,
      txWindow = 262144,
      rxWindow = 262144,
      rxWindowMax = 4194304,
      highWaterMark = 65536,
    }: {
      initiator?: boolean;
      target?: StreamTarget | null;
      txWindow?: number;
      rxWindow?: number;
      rxWindowMax?: number;
      highWaterMark?: number;
    } = {},
  ) {
    super({ highWaterMark, allowHalfOpen: true });
    this.mux = mux;
    this.id = id;
    this.initiator = initiator;
    this.target = target;
    this.txWindow = txWindow;

    this._rxGranted = rxWindow;
    this._rxWindowMax = Math.max(rxWindow, rxWindowMax);

    this._creditBatch = new Batch(
      (delta) => {
        if (this.destroyed) return;
        const p = Buffer.alloc(4);
        p.writeUInt32BE(delta >>> 0, 0);
        this.mux._sendControl(FT.WINDOW, this.id, p);
      },
      { threshold: Math.max(16384, Math.floor(rxWindow / 4)), intervalMs: 5 },
    );
  }

  // Methods below are package-internal (underscore convention); the MuxSession
  // drives the stream through them.
  _settleAck(err: Error | null, value: unknown = undefined): void {
    if (this._ackSettled) return;
    this._ackSettled = true;
    if (err) {
      this._ackErr = err;
      this._ackReject?.(err);
    } else {
      this._ackValue = value;
      this._ackResolve?.(this);
    }
  }

  _waitAck(): Promise<TunnelStream> {
    if (this._ackSettled) {
      return this._ackErr ? Promise.reject(this._ackErr) : Promise.resolve(this);
    }
    return new Promise((resolve, reject) => {
      this._ackResolve = resolve;
      this._ackReject = reject;
    });
  }

  /** Server: accept the inbound stream (sends OPEN_ACK ok). */
  accept(info: { upstream?: string | null } = {}): void {
    if (this._ackDone || this.initiator) return;
    this._ackDone = true;
    const body = Buffer.from(JSON.stringify({
      ok: true,
      compression: this.compression,
      upstream: info.upstream ?? null,
    }), 'utf8');
    this.mux._sendControl(FT.OPEN_ACK, this.id, body);
    this._ackResolve?.(this);
  }

  /** Server: reject the inbound stream (sends OPEN_ACK error). */
  reject(code = 'denied', reason = ''): void {
    if (this._ackDone || this.initiator) return;
    this._ackDone = true;
    const body = Buffer.from(JSON.stringify({ ok: false, code, reason }), 'utf8');
    this.mux._sendControl(FT.OPEN_ACK, this.id, body);
    const err: Error & { code?: string } = new Error(`stream rejected: ${code}${reason ? ' ' + reason : ''}`);
    err.code = code;
    this._ackReject?.(err);
    this._destroyLocal(null);
  }

  get remoteAddress(): string | null {
    if (!this.target) return null;
    if (this.target.unix) return `unix:${this.target.unix}`;
    return `${this.target.host ?? ''}:${this.target.port ?? 0}`;
  }

  /** Human-readable label, e.g. "TunnelStream#3(a.test:80)". */
  override toString(): string {
    return `TunnelStream#${this.id}${this.target ? `(${this.remoteAddress})` : ''}`;
  }

  // ---------------- write path ----------------

  override _write(chunk: Buffer, _enc: string, cb: (err?: Error | null) => void): void {
    if (this.destroyed) {
      cb(new Error('stream destroyed'));
      return;
    }
    // first-chunk content sniffing: pre-compressed payloads bypass compression
    // (per direction; the receiver decompresses nothing when no frame is flagged)
    if (!this._sniffed && this.compression !== ALGO_NONE && chunk.length > 0) {
      this._sniffed = true;
      if (looksPrecompressed(chunk)) this.compression = ALGO_NONE;
    }
    (async () => {
      let wire: Buffer = chunk;
      try {
        if (this.compression !== ALGO_NONE && chunk.length > 0) {
          this._comp ??= createCompressContext(this.compression, { level: this.compressionLevel });
          const a = await this._comp.write(chunk);
          const b = await this._comp.flush();
          const parts = [a, b].filter((p): p is Buffer => !!p);
          if (parts.length) wire = Buffer.concat(parts);
        }
      } catch (err) {
        cb(err as Error);
        return;
      }
      this._sendQ.push({ wire, logical: chunk.length, cbs: [cb], fin: false, off: 0, charged: 0 });
      this._pump();
    })();
  }

  override _final(cb: (err?: Error | null) => void): void {
    this._sendQ.push({ wire: Buffer.alloc(0), logical: 0, cbs: [cb], fin: true, off: 0, charged: 0 });
    this._pump();
  }

  _pump(): void {
    if (this._pumping || this.destroyed) return;
    this._pumping = true;
    (async () => {
      try {
        while (this._sendQ.length > 0 && !this.destroyed) {
          const item = this._sendQ[0]!;
          const done = await this._sendItem(item);
          if (!done) break; // credits or connection backpressure; will re-pump
          this._sendQ.shift();
          for (const c of item.cbs) c();
        }
      } catch (err) {
        this._teardownError(err as Error);
      } finally {
        this._pumping = false;
      }
      this._maybeAutoDestroy();
    })();
  }

  /**
   * Send one queue item (possibly across multiple DATA frames).
   * Credits are charged incrementally in *logical* (decompressed) bytes and
   * released by the receiver in the same unit, keeping the accounting symmetric
   * even when compression slightly inflates incompressible payloads.
   * Every frame of a compressed item carries FLAG.COMPRESSED — the receiver
   * feeds each into its continuous decompression context.
   * Returns true when fully sent; false when blocked on credits/backpressure.
   * Resumable: per-item progress lives on the item itself.
   */
  private async _sendItem(item: SendItem): Promise<boolean> {
    const maxData = this.mux.peerMaxDataFrame;
    const compressed = this.compression !== ALGO_NONE;
    while (item.off < item.wire.length) {
      if (item.charged < item.logical) {
        if (this.txWindow <= 0) return false; // waiting for WINDOW credits
        const charge = Math.min(this.txWindow, item.logical - item.charged);
        this.txWindow -= charge;
        item.charged += charge;
      }
      const take = Math.min(maxData, item.wire.length - item.off);
      const isLast = item.off + take >= item.wire.length;
      let flags = 0;
      if (compressed) flags |= FLAG.COMPRESSED;
      if (item.fin && isLast) flags |= FLAG.FIN;
      this.stats.framesTx++;
      const ok = await this.mux._writeData(
        this,
        encodeFrame(FT.DATA, flags, this.id, item.wire.subarray(item.off, item.off + take)),
      );
      item.off += take;
      if (!ok) return false; // mux socket backpressure; mux re-pumps on drain
    }
    if (item.fin && item.wire.length === 0) {
      // standalone zero-length FIN frame (empty final chunk)
      this.stats.framesTx++;
      await this.mux._writeData(this, encodeFrame(FT.DATA, FLAG.FIN, this.id, null));
    }
    if (item.fin) this._finSent = true;
    this.stats.bytesTx += item.logical;
    return true;
  }

  // ---------------- read path ----------------

  /**
   * Inbound frames must be applied strictly in arrival order (decompression
   * contexts are sequential and FIN must not overtake pending DATA), so every
   * deliver() is chained onto a per-stream serial promise.
   */
  deliver(payload: Buffer | null, flags: number): void {
    const run = this._deliverChain.then(() => this._deliverStep(payload, flags));
    this._deliverChain = run.catch((err: Error) => this._teardownError(err));
  }

  private async _deliverStep(payload: Buffer | null, flags: number): Promise<void> {
    if (this.destroyed || this._eofPushed) return;
    let buf: Buffer | null = payload;
    try {
      if ((flags & FLAG.COMPRESSED) && payload && payload.length > 0) {
        this._decomp ??= createDecompressContext(this.compression);
        const out = await this._decomp.write(payload);
        buf = out ?? Buffer.alloc(0);
      }
    } catch (err) {
      this._teardownError(err as Error);
      return;
    }
    this.stats.framesRx++;
    if (buf && buf.length > 0) this.stats.bytesRx += buf.length;
    const fin = (flags & FLAG.FIN) !== 0;
    if (fin) this._finReceived = true;
    if (buf && buf.length > 0) this._pendingRx.push(buf);
    if (fin) this._pendingRx.push(null);
    if (this._pendingRx.length > 0) this._flushPendingRx();
    else this._maybeAutoDestroy();
  }

  override _read(_size: number): void {
    this._flushPendingRx();
  }

  /**
   * Push buffered inbound data to the readable side.
   * Node's push() accepts data even when it returns false (the return value is
   * advisory), so the only reliable memory bound is our own gate:
   * push while the readable buffer is below its high-water mark. Credits are
   * issued only for pushed data, which in turn bounds the peer's send window.
   * When the gate is closed, a light retry timer keeps probing: consumers do
   * not always drive _read() (paused streams, async-iterator edge cases), and
   * pushing from outside _read() is legal.
   */
  private _flushPendingRx(): void {
    if (this._eofPushed) return;
    while (this._pendingRx.length > 0 && this.readableLength < this.readableHighWaterMark) {
      const item = this._pendingRx[0]!;
      if (item === null) {
        this._pendingRx.shift();
        this._eofPushed = true;
        this.push(null);
        this._clearRxRetry();
        break;
      }
      this.push(item);
      this._pendingRx.shift();
      this._credit(item.length);
    }
    if (this._pendingRx.length > 0 && !this._eofPushed) {
      this._scheduleRxRetry();
    } else {
      this._clearRxRetry();
    }
    this._maybeAutoDestroy();
  }

  private _scheduleRxRetry(): void {
    if (this._rxRetryTimer || this.destroyed) return;
    this._rxRetryTimer = setTimeout(() => {
      this._rxRetryTimer = null;
      if (!this.destroyed) this._flushPendingRx();
    }, 10);
    this._rxRetryTimer.unref();
  }

  private _clearRxRetry(): void {
    if (this._rxRetryTimer) {
      clearTimeout(this._rxRetryTimer);
      this._rxRetryTimer = null;
    }
  }

  private _credit(n: number): void {
    this._creditBatch.add(n);
    this._maybeGrowWindow(n);
  }

  /**
   * Dynamic window right-sizing: when consumption stays high across the
   * growth interval (100ms) and the app has drained its buffer at a quiet
   * evaluation point, the window is the bottleneck — double it (capped at
   * rxWindowMax). Evaluation is always deferred to a timer so the reader
   * gets a turn to drain first (at push time the buffer legitimately holds
   * the just-delivered chunk); unread buffered data at evaluation time
   * disqualifies growth, bounding memory for backpressured streams.
   */
  private _maybeGrowWindow(n: number): void {
    if (this._rxGranted >= this._rxWindowMax) return;
    this._consumedSinceGrow += n;
    if (this._consumedSinceGrow < Math.floor(this._rxGranted / 2)) return;
    if (this._growRetryTimer) return;
    const wait = Math.max(10, 100 - (Date.now() - this._growAt));
    this._growRetryTimer = setTimeout(() => {
      this._growRetryTimer = null;
      if (this.destroyed) return;
      if (Date.now() - this._growAt < 100) return;
      const buffered = this.readableLength + this._pendingRx.length;
      if (buffered * 10 >= this._rxGranted) return;
      const bonus = Math.min(this._rxGranted, this._rxWindowMax - this._rxGranted);
      if (bonus <= 0) return;
      this._rxGranted += bonus;
      this._consumedSinceGrow = 0;
      this._growAt = Date.now();
      const p = Buffer.alloc(4);
      p.writeUInt32BE(bonus >>> 0, 0);
      this.mux._sendControl(FT.WINDOW, this.id, p);
    }, wait);
    this._growRetryTimer.unref();
  }

  // ---------------- control ----------------

  addCredit(delta: number): void {
    if (this.destroyed) return;
    this.txWindow += delta;
    this._pump();
  }

  /** Abort: tell the peer we're gone and drop everything (like a TCP RST). */
  abort(code: number = CLOSE_CODES.CANCEL, reason = ''): void {
    if (this._closeSent || this.destroyed) return;
    this._closeSent = true;
    const reasonBuf = Buffer.from(String(reason).slice(0, 200), 'utf8');
    const body = Buffer.concat([Buffer.from([code & 0xff]), reasonBuf]);
    this.mux._sendControl(FT.CLOSE, this.id, body);
    this._destroyLocal(new Error(`stream aborted: ${code}${reason ? ' ' + reason : ''}`));
  }

  /** Peer sent CLOSE for this stream. */
  peerClosed(code: number, _reason: string): void {
    if (this.destroyed) return;
    if (code === CLOSE_CODES.EOS || code === CLOSE_CODES.CANCEL) {
      this._finReceived = true;
      if (!this._eofPushed) {
        this._pendingRx.push(null);
        this._flushPendingRx();
      }
      this._maybeAutoDestroy();
    } else {
      // peer aborted: surface as 'aborted' + reason, not as an unhandled 'error'
      this._destroySilent(`peer closed stream: code=${code}`);
    }
  }

  _teardownError(err: Error): void {
    if (!this._closeSent && !this.destroyed) {
      this._closeSent = true;
      const reason = Buffer.from(String(err?.message ?? 'error').slice(0, 60), 'utf8');
      this.mux._sendControl(FT.CLOSE, this.id, Buffer.concat([Buffer.from([CLOSE_CODES.ERROR]), reason]));
    }
    this._destroyLocal(err instanceof Error ? err : new Error(String(err)));
  }

  _destroyLocal(err: Error | null): void {
    if (this._destroying) return;
    this._destroying = true;
    this._creditBatch.dispose();
    this._comp?.destroy();
    this._decomp?.destroy();
    this.mux._unmapStream(this);
    if (err) this.destroy(err);
    else this.destroy();
  }

  /**
   * Library-initiated teardown that should not crash apps lacking 'error'
   * listeners: destroy without an error object, expose the reason separately.
   */
  _destroySilent(reason: string): void {
    if (this._destroying || this.destroyed) return;
    this.abortedReason = reason;
    try {
      this.emit('aborted', reason);
    } catch {
      /* listener errors are theirs */
    }
    this._destroyLocal(null);
  }

  private _maybeAutoDestroy(): void {
    if (
      this._finSent && this._finReceived &&
      this._sendQ.length === 0 && !this._pumping &&
      (this.readableEnded || this.readableLength === 0)
    ) {
      setImmediate(() => {
        if (this._destroying) return;
        if (this._finSent && this._finReceived && this._sendQ.length === 0) {
          this._destroyLocal(null);
        }
      });
    }
  }

  override _destroy(err: Error | null, cb: (error?: Error | null) => void): void {
    this._creditBatch.dispose();
    this._clearRxRetry();
    if (this._growRetryTimer) {
      clearTimeout(this._growRetryTimer);
      this._growRetryTimer = null;
    }
    super._destroy(err, cb);
  }
}

// Per-stream, per-direction compression contexts with *continuous* context:
// chunks are compressed/decompressed through persistent zlib transform streams and
// flushed at frame boundaries (like WebSocket permessage-deflate with context takeover).
//
// This port supports the "none" and "deflate" algorithms (raw DEFLATE via
// node:zlib with Z_SYNC_FLUSH at frame boundaries) — the subset negotiated with
// the Rust implementation's flate2-based deflate, which is byte-compatible.
//
// Determinism note: for zlib-family transforms, the write/flush callback fires only
// after the transform has pushed all output for that input; with a 'data' listener
// attached from construction (flowing mode), pushed output is collected synchronously.

import { Buffer } from 'node:buffer';
import zlib from 'node:zlib';

export const ALGO_NONE = 'none';
export const ALGO_DEFLATE = 'deflate';

/** Algorithms this runtime can actually compress/decompress. */
export const SUPPORTED: readonly string[] = [ALGO_NONE, ALGO_DEFLATE];

/** Context handle shared by both directions of one stream. */
export interface CompCtx {
  write(buf: Buffer): Promise<Buffer | null>;
  flush(): Promise<Buffer | null>;
  end(): Promise<Buffer | null>;
  destroy(): void;
}

class ZCtx implements CompCtx {
  private readonly z: zlib.DeflateRaw | zlib.InflateRaw;
  private readonly flushOp: number | undefined;
  private readonly parts: Buffer[] = [];
  private err: Error | null = null;

  constructor(z: zlib.DeflateRaw | zlib.InflateRaw, flushOp: number | undefined) {
    this.z = z;
    this.flushOp = flushOp;
    z.on('data', (d: Buffer) => this.parts.push(d));
    z.on('error', (e: Error) => {
      this.err = e;
    });
  }

  private _collect(): Buffer | null {
    if (this.parts.length === 0) return null;
    const out = Buffer.concat(this.parts);
    this.parts.length = 0;
    return out;
  }

  write(buf: Buffer): Promise<Buffer | null> {
    return new Promise((res, rej) => {
      if (this.err) return rej(this.err);
      this.z.write(buf, (e) => (e ? rej(e) : res(this._collect())));
    });
  }

  flush(): Promise<Buffer | null> {
    return new Promise((res, rej) => {
      if (this.err) return rej(this.err);
      // rest-arg wrapper: @types/node types the zlib flush callback as () => void,
      // but the runtime passes the error as the first argument.
      const done = (...args: [err?: Error | null]) => (args[0] ? rej(args[0]) : res(this._collect()));
      if (this.flushOp === undefined) this.z.flush(done); // stream-type default op
      else this.z.flush(this.flushOp, done);
    });
  }

  end(): Promise<Buffer | null> {
    return new Promise((res) => {
      if (this.err || this.z.destroyed || this.z.writableEnded) return res(null);
      this.z.end(() => res(this._collect()));
    });
  }

  /** Teardown: end() first so zlib releases its handles, then destroy(). */
  destroy(): void {
    if (this.z.destroyed) return;
    const finish = () => {
      if (!this.z.destroyed) this.z.destroy();
    };
    if (this.z.writableEnded || this.err) {
      finish();
    } else {
      this.z.once('close', finish);
      try {
        this.z.end();
      } catch {
        finish();
      }
      setTimeout(finish, 50).unref();
    }
  }
}

class PassCtx implements CompCtx {
  write(buf: Buffer): Promise<Buffer | null> {
    return Promise.resolve(buf.length ? buf : null);
  }

  flush(): Promise<Buffer | null> {
    return Promise.resolve(null);
  }

  async end(): Promise<Buffer | null> {
    return null;
  }

  destroy(): void {}
}

/** Cached list of algorithms usable on this runtime (['none', 'deflate']). */
export function supportedAlgorithms(): Promise<string[]> {
  _supported ??= Promise.resolve([...SUPPORTED]);
  return _supported;
}
let _supported: Promise<string[]> | null = null;

/**
 * Pick an algorithm from a request + peer's supported list. The result is always
 * an algorithm this runtime can handle (never e.g. 'brotli'/'zstd').
 */
export function negotiate(requested: string | null | undefined, peerSupported: readonly string[]): string {
  if (!requested || requested === ALGO_NONE) return ALGO_NONE;
  const base = baseAlgo(requested);
  const pick = (a: string): string | null => (peerSupported.includes(a) && SUPPORTED.includes(a) ? a : null);
  if (base === 'auto') {
    return pick(ALGO_DEFLATE) || ALGO_NONE;
  }
  return pick(base) || ALGO_NONE;
}

/** "deflate:9" -> "deflate" (level suffix stripped; unknown suffixes keep the base). */
export function baseAlgo(requested: string | null | undefined): string {
  const s = String(requested);
  const idx = s.indexOf(':');
  return idx === -1 ? s : s.slice(0, idx);
}

/** "deflate:9" -> 9; invalid/missing -> null. */
export function parseLevel(requested: string | null | undefined): number | null {
  const s = String(requested ?? '');
  const idx = s.indexOf(':');
  if (idx === -1) return null;
  const n = Number(s.slice(idx + 1));
  return Number.isInteger(n) && n >= 1 && n <= 22 ? n : null;
}

// Well-known magic prefixes: content that is already compressed. Streams whose
// first chunk matches are silently switched to 'none' (saves CPU, avoids the
// ~0.3% expansion). Applied per direction by the sender only.
const MAGIC_PREFIXES: Buffer[] = [
  Buffer.from([0x1f, 0x8b]),                   // gzip
  Buffer.from([0x28, 0xb5, 0x2f, 0xfd]),       // zstd
  Buffer.from([0x50, 0x4b, 0x03, 0x04]),       // zip
  Buffer.from([0x89, 0x50, 0x4e, 0x47]),       // png
  Buffer.from([0xff, 0xd8, 0xff]),             // jpeg
  Buffer.from([0x37, 0x7a, 0xbc, 0xaf]),       // 7z
  Buffer.from([0x52, 0x61, 0x72, 0x21]),       // rar
  Buffer.from([0x25, 0x50, 0x44, 0x46]),       // %PDF (not compressed, but incompressible-ish)
  Buffer.from([0x42, 0x5a, 0x68]),             // bzip2
];

/** Heuristic: does this first chunk look pre-compressed? */
export function looksPrecompressed(chunk: Buffer | null): boolean {
  if (!chunk || chunk.length < 4) return false;
  for (const magic of MAGIC_PREFIXES) {
    if (chunk.length >= magic.length && chunk.subarray(0, magic.length).equals(magic)) {
      return true;
    }
  }
  // ISO-BMFF (mp4/mov/heic): "....ftyp" at offset 4
  if (chunk.length >= 12 && chunk[4] === 0x66 && chunk[5] === 0x74 && chunk[6] === 0x79 && chunk[7] === 0x70) {
    return true;
  }
  return false;
}

/**
 * Create a sender-side compression context for one stream direction.
 * write(buf) -> Promise<Buffer|null>, flush() -> Promise<Buffer|null>,
 * end()/destroy() for teardown.
 */
export function createCompressContext(algo: string, { level }: { level?: number | null } = {}): CompCtx {
  switch (algo) {
    case ALGO_NONE:
      return new PassCtx();
    case ALGO_DEFLATE:
      return new ZCtx(
        zlib.createDeflateRaw({ level: level ?? 6, windowBits: 15, memLevel: 8 }),
        zlib.constants.Z_SYNC_FLUSH,
      );
    default:
      throw new Error(`unsupported compression algorithm: ${algo}`);
  }
}

/**
 * Create the matching receiver-side decompression context for one stream
 * direction; same interface as createCompressContext.
 */
export function createDecompressContext(algo: string): CompCtx {
  switch (algo) {
    case ALGO_NONE:
      return new PassCtx();
    case ALGO_DEFLATE:
      return new ZCtx(zlib.createInflateRaw({ windowBits: 15 }), undefined);
    default:
      throw new Error(`unsupported compression algorithm: ${algo}`);
  }
}

/**
 * Internal shared utilities: endpoint parsing, host-pattern matching for the
 * router, small timing/formatting helpers, and the batching primitive used
 * for window-credit updates. Nothing here is protocol-specific.
 */

import { Buffer } from 'node:buffer';

/** Minimal structured logger surface used across the SDK. */
export interface Logger {
  trace?: (msg: string, extra?: Record<string, unknown>) => void;
  debug: (msg: string, extra?: Record<string, unknown>) => void;
  info: (msg: string, extra?: Record<string, unknown>) => void;
  warn: (msg: string, extra?: Record<string, unknown>) => void;
  error: (msg: string, extra?: Record<string, unknown>) => void;
  child?: (suffix: string) => Logger;
}

/** A logger that swallows everything (the SDK default). */
export function noopLogger(): Logger {
  const fn = (): void => {};
  const log: Logger = {
    trace: fn, debug: fn, info: fn, warn: fn, error: fn,
    child: () => log,
  };
  return log;
}

/** Parsed endpoint / stream target. */
export interface ParsedTarget {
  host: string;
  port: number;
  unix?: string;
}

/** Anything parseTarget accepts: "host:port", "[v6]:port", ["host", port], or an object. */
export type TargetInput =
  | string
  | [string, number | string]
  | { host?: string | null; port?: number | string; unix?: string };

/** Parse "host:port" / "[v6]:port" / "host" with default port. */
export function parseTarget(str: TargetInput, defaultPort = 0): ParsedTarget {
  if (Array.isArray(str)) return { host: str[0]!, port: Number(str[1]) };
  if (typeof str === 'object' && str !== null) {
    if (str.unix !== undefined) return { host: '', port: 0, unix: str.unix };
    return { host: String(str.host ?? ''), port: Number(str.port ?? defaultPort) };
  }
  const s = String(str).trim();
  if (s.startsWith('[')) {
    const end = s.indexOf(']');
    if (end === -1) throw new Error(`invalid target: ${s}`);
    const host = s.slice(1, end);
    const rest = s.slice(end + 1);
    const port = rest.startsWith(':') ? Number(rest.slice(1)) : defaultPort;
    return { host, port };
  }
  const idx = s.lastIndexOf(':');
  if (idx === -1) return { host: s, port: defaultPort };
  const host = s.slice(0, idx);
  const port = Number(s.slice(idx + 1));
  if (!Number.isFinite(port)) throw new Error(`invalid target: ${s}`);
  return { host, port };
}

/** Lowercase, strip port and trailing dot. */
export function normalizeHost(h: unknown): string | null {
  if (!h) return null;
  let s = String(h).trim().toLowerCase();
  if (s.includes(':') && !s.startsWith('[')) s = s.slice(0, s.lastIndexOf(':')); // strip :port (v4/hostname)
  s = s.replace(/^\[/, '').replace(/\]$/, '').replace(/\.$/, '');
  return s || null;
}

/** Wildcard host match: "*", "*.example.com" (suffix, label-aware), exact. */
export function hostMatches(pattern: string, host: string): boolean {
  const p = normalizeHost(pattern);
  const h = normalizeHost(host);
  if (!p || !h) return false;
  if (p === '*' || p === h) return true;
  if (p.startsWith('*.')) {
    const suffix = p.slice(1); // ".example.com"
    return h.endsWith(suffix) && !h.slice(0, -suffix.length).endsWith('.');
  }
  return false;
}

/** Promise-based sleep (ms). */
export function sleep(ms: number): Promise<void> {
  return new Promise((r) => setTimeout(r, ms));
}

/** Random hex id of `bytes` bytes (non-crypto; ids only, never secrets). */
export function randomId(bytes = 8): string {
  const b = Buffer.allocUnsafe(bytes);
  b.fill(0);
  for (let i = 0; i < bytes; i++) b[i] = (Math.random() * 256) | 0;
  return b.toString('hex');
}

/** Human-readable byte count, e.g. "1.50MB". */
export function fmtBytes(n: number): string {
  if (!Number.isFinite(n)) return String(n);
  const u = ['B', 'KB', 'MB', 'GB', 'TB'];
  let i = 0;
  let v = n;
  while (v >= 1024 && i < u.length - 1) {
    v /= 1024;
    i++;
  }
  return `${v.toFixed(v >= 100 || i === 0 ? 0 : 2)}${u[i]}`;
}

/** Monotonic-ish millisecond timestamp (hrtime-based, for stats/RTT). */
export function nowMs(): number {
  return Number(process.hrtime.bigint() / 1000000n);
}

/** Normalize config value: single item -> array. */
export function toArray<T>(v: T | T[] | undefined | null): T[] {
  if (v === undefined || v === null) return [];
  return Array.isArray(v) ? v : [v];
}

/** Accumulate-and-flush batching helper. */
export class Batch {
  private readonly _flushFn: (v: number) => void;
  private readonly _threshold: number;
  private readonly _intervalMs: number;
  private _acc = 0;
  private _timer: NodeJS.Timeout | null = null;

  constructor(flushFn: (v: number) => void, { threshold = 1, intervalMs = 5 }: { threshold?: number; intervalMs?: number } = {}) {
    this._flushFn = flushFn;
    this._threshold = threshold;
    this._intervalMs = intervalMs;
  }

  add(n: number): void {
    this._acc += n;
    if (this._acc >= this._threshold) {
      this.flush();
      return;
    }
    if (!this._timer) {
      this._timer = setTimeout(() => this.flush(), this._intervalMs);
      this._timer.unref();
    }
  }

  flush(): void {
    if (this._timer) {
      clearTimeout(this._timer);
      this._timer = null;
    }
    if (this._acc > 0) {
      const v = this._acc;
      this._acc = 0;
      this._flushFn(v);
    }
  }

  dispose(): void {
    if (this._timer) {
      clearTimeout(this._timer);
      this._timer = null;
    }
    this._acc = 0;
  }
}

const LEVELS: Record<string, number> = { trace: 10, debug: 20, info: 30, warn: 40, error: 50, silent: 100 };

/**
 * Create a structured logger (levelled text or JSON lines). Zero dependencies.
 */
export function createLog(
  { level = 'info', name = 'krymux', json = false, sink = null }: {
    level?: string;
    name?: string;
    json?: boolean;
    sink?: ((...a: unknown[]) => void) | null;
  } = {},
): Logger {
  const threshold = LEVELS[level] ?? LEVELS.info;
  const write = sink ?? ((...a: unknown[]) => console.error(...a));

  function emit(lvl: 'trace' | 'debug' | 'info' | 'warn' | 'error', msg: string, extra?: Record<string, unknown>): void {
    if ((LEVELS[lvl] ?? 100) < threshold) return;
    const ts = new Date().toISOString();
    if (json) {
      write(JSON.stringify({ ts, level: lvl, name, msg, ...extra }));
    } else {
      const e = extra && Object.keys(extra).length ? ' ' + JSON.stringify(extra) : '';
      write(`${ts} ${lvl.toUpperCase().padEnd(5)} [${name}] ${msg}${e}`);
    }
  }

  const log: Logger = {
    trace: (m, x) => emit('trace', m, x),
    debug: (m, x) => emit('debug', m, x),
    info: (m, x) => emit('info', m, x),
    warn: (m, x) => emit('warn', m, x),
    error: (m, x) => emit('error', m, x),
    child(suffix: string): Logger {
      return createLog({ level, name: `${name}:${suffix}`, json, sink });
    },
  };
  return log;
}

// TLS 1.3 security layer.
//
// - Encryption/transport integrity: standard TLS 1.3 (OpenSSL, hardware AES-GCM or
//   ChaCha20-Poly1305). We do NOT hand-roll a handshake.
// - Mutual identity: both sides present self-signed Ed25519 certificates generated
//   by this tool. The certificate is treated as a key container; the canonical
//   identity is sha256(SPKI) — exactly the WireGuard/SSH "public key" model.
// - Server authorization: whitelist of client key fingerprints, or "open" mode
//   (any valid key). Client authorization: pinned server key fingerprint.
// - TLS 1.3 session resumption is contained: fresh random ticketKeys per process
//   (tickets die on restart), ticketKeys rotated whenever the whitelist changes,
//   and connections that present no client certificate (e.g. resumed sessions
//   where OpenSSL does not re-send it) are rejected — fail closed.
//
// Wire facts shared with the Rust implementation (crates/krymux/src/tls.rs):
// ALPN "krymux", TLS 1.3 only, mTLS with Ed25519 self-signed certs.

import { Buffer } from 'node:buffer';
import { randomBytes } from 'node:crypto';
import type * as tls from 'node:tls';
import { peerFingerprint } from './keys.js';
import { toArray } from './util.js';

export const ALPN = 'krymux';

/** TLS server options that require a client certificate without CA validation. */
export function serverTlsOptions({ cert, key, handshakeTimeout = 10000 }: {
  cert: string;
  key: string;
  handshakeTimeout?: number;
}): tls.TlsOptions {
  return {
    cert,
    key,
    ALPNProtocols: [ALPN],
    minVersion: 'TLSv1.3',
    requestCert: true,
    rejectUnauthorized: false, // we authorize by fingerprint below
    handshakeTimeout,
    ticketKeys: randomBytes(48), // per-process; rotated on auth changes
  };
}

/** Compiled runtime authorization state. */
export interface CompiledAuth {
  mode: 'open' | 'whitelist';
  fingerprints: Set<string>;
}

/** Authorization input shape ({ mode, fingerprints[] } or { mode, clients[] }). */
export interface AuthConfig {
  mode?: string;
  fingerprints?: Array<string | { fingerprint?: string; publicKey?: string }>;
  clients?: Array<string | { fingerprint?: string; publicKey?: string }>;
}

/** Normalize an `auth` config block into the runtime shape. */
export function compileAuth(authCfg: AuthConfig = {}, normalizeFingerprintFn: (s: string) => string): CompiledAuth {
  const mode = authCfg.mode === 'open' ? 'open' : 'whitelist';
  const fingerprints = new Set<string>();
  for (const entry of toArray(authCfg.fingerprints ?? authCfg.clients ?? [])) {
    let fp: string | undefined;
    if (typeof entry === 'object' && entry !== null) fp = entry.fingerprint ?? entry.publicKey;
    else fp = entry;
    if (!fp) continue;
    fingerprints.add(normalizeFingerprintFn(fp));
  }
  return { mode, fingerprints };
}

/** Verdict of a post-handshake authorization check. */
export interface AuthVerdict {
  ok: boolean;
  reason?: string;
  fingerprint?: string;
}

/**
 * Decide whether a freshly handshaked server-side TLS connection may proceed.
 * Fail closed: no ALPN match, no cert, unknown fingerprint -> reject.
 */
export function authorizePeer(tlsSocket: tls.TLSSocket, auth: CompiledAuth): AuthVerdict {
  if (tlsSocket.alpnProtocol !== ALPN) {
    return { ok: false, reason: `alpn mismatch: ${tlsSocket.alpnProtocol ?? 'none'}` };
  }
  const fp = peerFingerprint(tlsSocket);
  if (!fp) {
    // covers: no client cert, empty cert (resumed session without cert re-send)
    return { ok: false, reason: 'no client certificate presented' };
  }
  if (auth.mode === 'open') return { ok: true, fingerprint: fp };
  if (auth.fingerprints.has(fp)) return { ok: true, fingerprint: fp };
  return { ok: false, reason: `client fingerprint not whitelisted: ${fp.slice(0, 22)}...` };
}

/** TLS client options; identity is always sent, trust is decided by pinning. */
export function clientTlsOptions({ cert, key, servername = 'krymux' }: {
  cert: string;
  key: string;
  servername?: string;
}): tls.ConnectionOptions {
  return {
    cert,
    key,
    ALPNProtocols: [ALPN],
    minVersion: 'TLSv1.3',
    rejectUnauthorized: false, // we verify the pinned fingerprint ourselves
    servername,
    checkServerIdentity: () => undefined, // pin, do not use CA/name validation
  };
}

/** Verify the server's pinned key fingerprint after the TLS handshake. */
export function verifyServerPin(tlsSocket: tls.TLSSocket, expectedFingerprint: string): AuthVerdict {
  const fp = peerFingerprint(tlsSocket);
  if (!fp) return { ok: false, reason: 'server did not present a certificate' };
  if (fp !== expectedFingerprint) {
    return { ok: false, reason: `server fingerprint mismatch: got ${fp.slice(0, 22)}...` };
  }
  return { ok: true, fingerprint: fp };
}

// Routing: decides, for each inbound stream target ({host, port}), which upstream
// to dial — a configured route, the fallback upstream, the client-specified target
// (if allowed), or deny.

import { hostMatches, normalizeHost, toArray } from './util.js';

/** A dialable upstream: {host, port} or {unix}. */
export interface UpstreamAddr {
  host?: string;
  port?: number;
  unix?: string;
}

/** Anything that can name an upstream: "host:port", "unix:/path", [host, port], object. */
export type UpstreamInput = string | [string, number | string] | UpstreamAddr | null | undefined;

/** A single configured route. */
export interface RouteConfig {
  host?: string | string[];
  hosts?: string | string[];
  port?: PortPatterns;
  ports?: PortPatterns;
  upstream?: UpstreamInput;
}

/** A single port pattern: number, "80", "*", "1000-2000", [lo, hi], {min, max}. */
export type PortPattern = number | string | [number, number] | { min?: number; max?: number };
/** One pattern or a list of patterns. */
export type PortPatterns = PortPattern | PortPattern[];

/** Client-dial permission block. */
export interface ClientTargetsConfig {
  enabled?: boolean;
  allowHosts?: string | string[];
  allowPorts?: PortPatterns | null;
}

/** Compiled route (internal). */
export interface CompiledRoute {
  order: number;
  hosts: string[];
  ports: PortPatterns | null;
  upstream: UpstreamAddr | null;
}

/** Resolver verdict for one inbound stream target. */
export type RouteDecision =
  | { action: 'route'; route: number; upstream: UpstreamAddr | null }
  | { action: 'dial'; target: UpstreamAddr }
  | { action: 'deny'; reason: string };

function compileUpstream(u: UpstreamInput): UpstreamAddr | null {
  if (!u) return null;
  if (typeof u === 'string') {
    const idx = u.lastIndexOf(':');
    if (u.startsWith('unix:')) return { unix: u.slice(5) };
    return { host: u.slice(0, idx), port: Number(u.slice(idx + 1)) };
  }
  if (Array.isArray(u)) return { host: u[0], port: Number(u[1]) };
  if ((u as UpstreamAddr).unix !== undefined) return { unix: (u as UpstreamAddr).unix };
  return { host: (u as UpstreamAddr).host ?? '127.0.0.1', port: Number((u as UpstreamAddr).port ?? 0) };
}

function portMatches(patterns: PortPatterns, port: number): boolean {
  for (const p of toArray(patterns)) {
    if (typeof p === 'number') {
      if (p === port) return true;
      continue;
    }
    if (Array.isArray(p) || typeof p === 'object') {
      const lo = Array.isArray(p) ? p[0] : p.min ?? 0;
      const hi = Array.isArray(p) ? p[1] : p.max ?? 65535;
      if (port >= Number(lo) && port <= Number(hi)) return true;
      continue;
    }
    const s = String(p);
    if (s === '*' || s === String(port)) return true;
    const dash = s.match(/^(\d+)-(\d+)$/);
    if (dash && port >= Number(dash[1]) && port <= Number(dash[2])) return true;
  }
  return false;
}

/**
 * Compile a routing config into a resolver.
 * @param opts.routes ordered [{host|hosts, port|ports, upstream}]
 * @param opts.fallbackUpstream used when no route matches
 * @param opts.clientTargets {enabled, allowHosts, allowPorts} —
 *   when enabled, otherwise-unrouted streams may dial their requested target
 * @returns {resolve, routes, fallback} — resolve(target) returns
 *   {action:'route', upstream} | {action:'dial', target} | {action:'deny', reason}
 */
export function compileRoutes(
  { routes = [], fallbackUpstream = null, clientTargets = null }: {
    routes?: RouteConfig | RouteConfig[];
    fallbackUpstream?: UpstreamInput;
    clientTargets?: ClientTargetsConfig | boolean | null;
  } = {},
): { resolve: (target: { host?: string | null; port?: number; unix?: string | null }) => RouteDecision; routes: CompiledRoute[]; fallback: UpstreamAddr | null } {
  const compiled: CompiledRoute[] = toArray(routes).map((r, i) => ({
    order: i,
    hosts: toArray(r.host ?? r.hosts ?? []).map((h) => normalizeHost(h)).filter((h): h is string => !!h),
    ports: (r.port ?? r.ports ?? null) as PortPatterns | null,
    upstream: compileUpstream(r.upstream),
  }));

  const fallback = compileUpstream(fallbackUpstream);

  let ct: { allowHosts: string[]; allowPorts: PortPatterns | null } | null = null;
  if (clientTargets) {
    const enabled = clientTargets === true || clientTargets.enabled === true;
    if (enabled) {
      const cfg = clientTargets === true ? {} : clientTargets;
      ct = {
        allowHosts: toArray((cfg as ClientTargetsConfig).allowHosts ?? ['*']),
        allowPorts: (cfg as ClientTargetsConfig).allowPorts ?? null, // null = any
      };
    }
  }

  function resolve(target: { host?: string | null; port?: number; unix?: string | null }): RouteDecision {
    const host = normalizeHost(target?.host);
    const port = Number(target?.port ?? 0);
    for (const r of compiled) {
      const hostOk = r.hosts.length === 0 || (host != null && r.hosts.some((h) => hostMatches(h, host)));
      const portOk = r.ports == null || portMatches(r.ports, port);
      if (hostOk && portOk) {
        return { action: 'route', route: r.order, upstream: r.upstream ?? fallback };
      }
    }
    if (fallback) return { action: 'route', route: -1, upstream: fallback };
    if (ct) {
      const hostOk = host == null || ct.allowHosts.some((p) => hostMatches(p, host));
      const portOk = ct.allowPorts == null || portMatches(ct.allowPorts, port);
      if (hostOk && portOk && (port > 0 || target?.unix)) {
        return { action: 'dial', target: target?.unix ? { unix: target.unix } : { host: target?.host ?? undefined, port } };
      }
      return { action: 'deny', reason: 'client target not allowed' };
    }
    return { action: 'deny', reason: 'no route matched and client targets are disabled' };
  }

  return { resolve, routes: compiled, fallback };
}

// EctunClient: SDK client. Connects to the tunnel endpoint, pins the server's
// key fingerprint, and exposes full-duplex logical streams.

import { EventEmitter } from 'node:events';
import * as tls from 'node:tls';
import type { TLSSocket } from 'node:tls';
import { MuxSession } from './mux.js';
import type { MuxStats, OpenStreamOptions } from './mux.js';
import { clientTlsOptions, verifyServerPin } from './tlsctx.js';
import { parseTarget, type Logger } from './util.js';

/** EctunClient.connect() options. */
export interface ConnectOptions {
  /** "host:port" tunnel endpoint. */
  endpoint: string | [string, number];
  /** Client identity ({certPem, keyPem, fingerprint}) from generateIdentity/loadIdentity. */
  identity: { certPem: string; keyPem: string };
  /** Pinned server key fingerprint ("sha256:..."). */
  serverFingerprint: string;
  /** Compression default for opened streams: none|deflate|auto. */
  compression?: string;
  keepaliveSec?: number;
  connectTimeoutMs?: number;
  name?: string;
  log?: Logger | null;
  tlsOpts?: tls.ConnectionOptions;
  rxWindow?: number;
  rxWindowMax?: number;
}

/**
 * SDK tunnel client. Connect via the static EctunClient.connect() factory,
 * then openStream() logical streams, ping(), and close(). Emits 'close' when
 * the underlying session ends.
 */
export class EctunClient extends EventEmitter {
  #session: MuxSession | null = null;
  #tlsSocket: TLSSocket | null = null;
  #serverFp: string | null = null;
  #closed = false;
  compressionDefault: string = 'auto';

  get session(): MuxSession | null {
    return this.#session;
  }

  get fingerprint(): string | null {
    return this.#serverFp;
  }

  get stats(): MuxStats | null {
    return this.#session?.stats ?? null;
  }

  /**
   * Connect to a tunnel server, pinning its fingerprint.
   * Resolves with a ready EctunClient; rejects on TLS/pin/handshake failure.
   */
  static async connect({
    endpoint,
    identity,
    serverFingerprint,
    compression = 'auto',
    keepaliveSec = 30,
    connectTimeoutMs = 10000,
    name = 'client',
    log = null,
    tlsOpts = {},
    rxWindow = 262144,
    rxWindowMax = 4194304,
  }: ConnectOptions): Promise<EctunClient> {
    if (!identity?.certPem || !identity?.keyPem) throw new Error('client identity required');
    if (!serverFingerprint) throw new Error('serverFingerprint required (pin the server key)');
    const target = parseTarget(endpoint, 0);

    const self = new EctunClient();
    const logger: Logger = log ?? { info() {}, warn() {}, error() {}, debug() {} };

    const tlsSocket = tls.connect({
      host: target.host,
      port: target.port,
      ...clientTlsOptions({ cert: identity.certPem, key: identity.keyPem }),
      ...tlsOpts,
    });
    self.#tlsSocket = tlsSocket;
    tlsSocket.setTimeout(connectTimeoutMs);

    try {
      await new Promise<void>((resolve, reject) => {
        const onTimeout = () => reject(new Error(`connect timeout to ${target.host}:${target.port}`));
        tlsSocket.once('secureConnect', resolve);
        tlsSocket.once('error', reject);
        tlsSocket.once('timeout', onTimeout);
      });
    } catch (err) {
      tlsSocket.destroy();
      throw err;
    }
    tlsSocket.setTimeout(0);

    const pin = verifyServerPin(tlsSocket, serverFingerprint);
    if (!pin.ok) {
      tlsSocket.destroy();
      const e: Error & { code?: string } = new Error(`server verification failed: ${pin.reason}`);
      e.code = 'PIN_MISMATCH';
      throw e;
    }
    self.#serverFp = pin.fingerprint ?? null;
    logger.info?.('tunnel established', { server: `${target.host}:${target.port}`, fp: (pin.fingerprint ?? '').slice(7, 19) });

    const session = new MuxSession(tlsSocket, {
      isClient: true,
      name,
      log: logger,
      keepaliveSec,
      rxWindow,
      rxWindowMax,
    });
    self.#session = session;
    try {
      await session.ready();
    } catch (err) {
      tlsSocket.destroy();
      throw err;
    }

    self.#closed = false;
    session.on('close', (reason: unknown) => {
      if (self.#closed) return;
      self.#closed = true;
      self.emit('close', reason);
    });

    self.compressionDefault = compression;
    return self;
  }

  /** Open a logical stream. Resolves after the server acknowledges. */
  openStream({ host = null, port = 0, unix = null, compression, hint = 'raw', meta = undefined }: Omit<OpenStreamOptions, 'compression'> & { compression?: string } = {}): Promise<import('./stream.js').TunnelStream> {
    if (!this.#session) return Promise.reject(new Error('not connected'));
    return this.#session.openStream({
      host, port, unix, hint, meta,
      compression: compression ?? this.compressionDefault ?? 'auto',
    });
  }

  /** RTT probe through the live session; resolves to milliseconds. */
  ping(): Promise<number> | undefined {
    return this.#session?.ping();
  }

  /** Graceful shutdown (GOAWAY) or immediate teardown when connected. */
  close(reason = 'client shutdown'): void {
    this.#closed = true;
    this.#session?.close(reason);
  }
}
